window.TOAN9_DATA = [{"n":1,"en":"CONCEPT OF EQUATIONS AND SYSTEMS OF TWO LINEAR EQUATIONS IN TWO VARIABLES","vi":"KHÁI NIỆM PHƯƠNG TRÌNH VÀ HỆ HAI PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN","page":1,"focus":"","cards":[{"t":"equation","pos":"noun","ipa":"/ɪˈkweɪ.ʒən/","vi":"phương trình","ex":"The equation x + y = 17 represents the total number of fruits."},{"t":"linear equation","pos":"noun phrase","ipa":"/ˈlɪn.i.ə ɪˈkweɪ.ʒən/","vi":"phương trình bậc nhất","ex":"A linear equation in two variables has the general form ax + by = c."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"biến số / ẩn số","ex":"In the equation 2x − y = 3, x and y are the variables."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"The coefficient of x in the expression 4x + 3y is 4."},{"t":"constant","pos":"noun","ipa":"/ˈkɒn.stənt/","vi":"hằng số","ex":"In ax + by = c, the letters a, b, and c represent constants."},{"t":"solution","pos":"noun","ipa":"/səˈluː.ʃən/","vi":"nghiệm","ex":"The pair (2; −1) is a solution of the equation 4x + 3y = 5."},{"t":"system of equations","pos":"noun phrase","ipa":"/ˈsɪs.təm əv ɪˈkweɪ.ʒənz/","vi":"hệ phương trình","ex":"Solve the system of equations x + y = 17 and 10x + 3y = 100."},{"t":"unknown","pos":"noun","ipa":"/ʌnˈnəʊn/","vi":"đại lượng chưa biết / ẩn","ex":"We use x and y to represent the unknowns in this word problem."},{"t":"pair of numbers","pos":"noun phrase","ipa":"/peə əv ˈnʌm.bəz/","vi":"cặp số","ex":"Each solution of a two-variable equation is represented as a pair of numbers (x; y)."},{"t":"coordinate plane","pos":"noun phrase","ipa":"/kəʊˈɔː.dɪ.nət pleɪn/","vi":"mặt phẳng tọa độ","ex":"We plot the system of equations on a 2D coordinate plane."},{"t":"axis","pos":"noun","ipa":"/ˈæk.sɪs/","vi":"trục tọa độ","ex":"The vertical axis is the y-axis, and the horizontal axis is the x-axis."},{"t":"origin","pos":"noun","ipa":"/ˈɒr.ɪ.dʒɪn/","vi":"gốc tọa độ","ex":"The origin O has the coordinates (0; 0) in the Cartesian plane."},{"t":"straight line","pos":"noun phrase","ipa":"/streɪt laɪn/","vi":"đường thẳng","ex":"The graph of the linear equation x + 2y = 3 is a straight line."},{"t":"intersection","pos":"noun","ipa":"/ˌɪn.təˈsek.ʃən/","vi":"giao điểm","ex":"The intersection of the two lines represents the unique solution of the system."},{"t":"parallel","pos":"adjective","ipa":"/ˈpær.ə.lel/","vi":"song song","ex":"Parallel lines never intersect, representing a system with no solution."},{"t":"coincident","pos":"adjective","ipa":"/kəʊˈɪn.sɪ.dənt/","vi":"trùng nhau","ex":"If two lines are coincident, they have infinitely many points in common."},{"t":"infinitely many","pos":"adjective phrase","ipa":"/ˈɪn.fɪ.nət.li ˈmen.i/","vi":"vô số","ex":"The equation x + 2y = 5 has infinitely many solutions."},{"t":"unique","pos":"adjective","ipa":"/juːˈniːk/","vi":"duy nhất","ex":"A system of intersecting lines has a unique solution."},{"t":"no solution","pos":"phrase","ipa":"/nəʊ səˈluː.ʃən/","vi":"vô nghiệm","ex":"The system of parallel lines has no solution."},{"t":"represent","pos":"verb","ipa":"/ˌrep.rɪˈzent/","vi":"biểu diễn / biểu thị","ex":"We can geometrically represent each solution as a point in the coordinate plane."}],"dlg":[{"who":"Teacher","text":"Class, let's represent the ancient puzzle of 17 cam and quýt using variables x and y."},{"who":"Student","text":"We can write our first linear equation: x + y = 17!"},{"who":"Teacher","text":"Excellent! Now, if we divide mandarins into 3 pieces and oranges into 10, how do we write the second equation?"},{"who":"Student","text":"We get 10x + 3y = 100!"},{"who":"Teacher","text":"Correct! Now we have a system of equations. How do we find the solution geometrically?"},{"who":"Student","text":"We plot both lines on the coordinate plane. Their intersection is the unique solution!"},{"who":"Teacher","text":"The intersection point is (7; 10). That pair of numbers is the unique solution!"},{"who":"Student","text":"Perfect! That means there are exactly 7 cams and 10 quýts. Great job, class!"}],"extras":[]},{"n":2,"en":"SOLVING SYSTEMS OF TWO LINEAR EQUATIONS IN TWO VARIABLES","vi":"GIẢI HỆ HAI PHƯƠNG TRÌNH BẬC NHẤT HAI ẨN","page":2,"focus":"","cards":[{"t":"system of linear equations","pos":"noun phrase","ipa":"/ˈsɪs.təm əv ˈlɪn.i.ə ɪˈkweɪ.ʒənz/","vi":"hệ phương trình bậc nhất","ex":"Solve the system of linear equations: x + y = 3 and 2x − 3y = 1."},{"t":"linear equation","pos":"noun phrase","ipa":"/ˈlɪn.i.ə ɪˈkweɪ.ʒən/","vi":"phương trình bậc nhất","ex":"A linear equation in two variables has the general form ax + by = c."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"ẩn số / biến số","ex":"In the system of equations, x and y are the variables to be found."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"In the equation 5x − 7y = 9, the coefficient of x is 5 and of y is −7."},{"t":"constant","pos":"noun","ipa":"/ˈkɒn.stənt/","vi":"hằng số / số hạng tự do","ex":"In the linear equation ax + by = c, the term c is the constant."},{"t":"substitution method","pos":"noun phrase","ipa":"/ˌsʌb.stɪˈtjuː.ʃən ˈmeθ.əd/","vi":"phương pháp thế","ex":"Express x from the first equation, then use the substitution method to solve."},{"t":"elimination method","pos":"noun phrase","ipa":"/ɪˌlɪm.ɪˈneɪ.ʃən ˈmeθ.əd/","vi":"phương pháp cộng đại số","ex":"We use the elimination method to eliminate y by adding the two equations."},{"t":"solution","pos":"noun","ipa":"/səˈluː.ʃən/","vi":"nghiệm","ex":"The ordered pair (2; 1) is the solution to the system."},{"t":"unique solution","pos":"noun phrase","ipa":"/juːˈniːk səˈluː.ʃən/","vi":"nghiệm duy nhất","ex":"If the two lines intersect at exactly one point, the system has a unique solution."},{"t":"infinitely many solutions","pos":"noun phrase","ipa":"/ˈɪn.fɪ.nət.li ˈmen.i səˈluː.ʃənz/","vi":"vô số nghiệm","ex":"When two linear equations represent the same line, the system has infinitely many solutions."},{"t":"no solution","pos":"noun phrase","ipa":"/nəʊ səˈluː.ʃən/","vi":"vô nghiệm","ex":"Since the parallel lines never meet, the system of equations has no solution."},{"t":"substitute","pos":"verb","ipa":"/ˈsʌb.stɪ.tjuːt/","vi":"thế vào / thay thế","ex":"Substitute y = 1 into the equation to calculate the value of x."}],"dlg":[{"who":"Teacher","text":"Can we solve this system of equations using the substitution method?"},{"who":"Student","text":"Yes! We can express y as 3 − x first!"},{"who":"Teacher","text":"Excellent! Now we substitute it into the second equation: 2x − 3(3 − x) = 1."},{"who":"Student","text":"Wow, now it becomes a basic linear equation with only one variable!"},{"who":"Teacher","text":"Correct! What is the unique solution of this system?"},{"who":"Student","text":"The unique solution is the ordered pair (2; 1)!"}],"extras":[]},{"n":3,"en":"SOLVING WORD PROBLEMS BY SETTING UP A SYSTEM OF EQUATIONS","vi":"GIẢI BÀI TOÁN BẰNG CÁCH LẬP HỆ PHƯƠNG TRÌNH","page":3,"focus":"","cards":[{"t":"word problem","pos":"noun phrase","ipa":"/ˈwɜːd ˌprɒb.ləm/","vi":"bài toán có lời văn / bài toán thực tế","ex":"We will learn how to solve a word problem by setting up a system of equations."},{"t":"set up","pos":"phrasal verb","ipa":"/set ʌp/","vi":"thiết lập / lập","ex":"The first step is to set up a system of equations representing the relationship between the quantities."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"ẩn số / biến số","ex":"Let x and y be the variables representing the unknown quantities of copper and zinc."},{"t":"unknown","pos":"noun","ipa":"/ʌnˈnəʊn/","vi":"đại lượng chưa biết / ẩn","ex":"We choose two variables to represent the two unknowns in the problem."},{"t":"condition","pos":"noun","ipa":"/kənˈdɪʃ.ən/","vi":"điều kiện","ex":"We must find a suitable condition for the variables, such as x and y being positive integers."},{"t":"express","pos":"verb","ipa":"/ɪkˈspres/","vi":"biểu thị / biểu diễn","ex":"Express the total volume of the alloy in terms of x and y."},{"t":"quantity","pos":"noun","ipa":"/ˈkwɒn.tə.ti/","vi":"đại lượng","ex":"We represent the unknown quantities in the word problem using variables."},{"t":"relationship","pos":"noun","ipa":"/rɪˈleɪ.ʃən.ʃɪp/","vi":"mối quan hệ","ex":"Set up equations to show the relationship between the variables."},{"t":"system of equations","pos":"noun phrase","ipa":"/ˈsɪs.təm əv ɪˈkweɪ.ʒənz/","vi":"hệ phương trình","ex":"Solve the system of equations to find the values of both unknowns."},{"t":"solve","pos":"verb","ipa":"/sɒlv/","vi":"giải","ex":"Solve the system to get the values of x and y."}],"dlg":[],"extras":[{"title":"Note","text":"Use these key words to understand and solve word problems by setting up a system of equations."}],"note":"Bài 3 chỉ có 10 từ và không có hội thoại trong tài liệu gốc."},{"n":4,"en":"EQUATIONS REDUCIBLE TO A LINEAR EQUATION IN ONE VARIABLE","vi":"PHƯƠNG TRÌNH QUY VỀ PHƯƠNG TRÌNH BẬC NHẤT MỘT ẨN","page":4,"focus":"","cards":[{"t":"reducible equation","pos":"noun phrase","ipa":"/rɪˈdjuː.sə.bəl ɪˈkweɪ.ʒən/","vi":"phương trình quy về được","ex":"We can transform complex equations into a reducible equation of first degree."},{"t":"product equation","pos":"noun phrase","ipa":"/ˈprɒd.ʌkt ɪˈkweɪ.ʒən/","vi":"phương trình tích","ex":"The equation (2x + 1)(3x − 1) = 0 is a product equation."},{"t":"equation with variables in the denominator","pos":"noun phrase","ipa":"/ɪˈkweɪ.ʒən wɪð ˈveə.ri.ə.bəlz ɪn ðə dɪˈnɒm.ɪ.neɪ.tə/","vi":"phương trình chứa ẩn ở mẫu","ex":"We must find the domain of an equation with variables in the denominator."},{"t":"defined condition","pos":"noun phrase","ipa":"/dɪˈfaɪnd kənˈdɪʃ.ən/","vi":"điều kiện xác định (ĐKXĐ)","ex":"The defined condition of the equation 5x over x − 1 equals zero is that x is not equal to 1."},{"t":"factor","pos":"noun","ipa":"/ˈfæk.tə/","vi":"nhân tử","ex":"In the product equation, we set each factor equal to zero."},{"t":"factorization","pos":"noun","ipa":"/ˌfæk.tər.aɪˈzeɪ.ʃən/","vi":"phân tích thành nhân tử","ex":"Use factorization to convert x² − x = 0 into x(x − 1) = 0."},{"t":"denominator","pos":"noun","ipa":"/dɪˈnɒm.ɪ.neɪ.tə/","vi":"mẫu thức / mẫu số","ex":"To solve a fractional equation, find the common denominator of all terms."},{"t":"numerator","pos":"noun","ipa":"/ˈnjuː.mə.reɪ.tə/","vi":"tử thức / tử số","ex":"After clearing the denominator, we equate the numerator to zero."},{"t":"common denominator","pos":"noun phrase","ipa":"/ˈkɒm.ən dɪˈnɒm.ɪ.neɪ.tə/","vi":"mẫu thức chung","ex":"The common denominator of 1 over x − 1 and x over x + 1 is (x − 1)(x + 1)."},{"t":"clear denominators","pos":"verb phrase","ipa":"/klɪə dɪˈnɒm.ɪ.neɪ.təz/","vi":"khử mẫu","ex":"Multiply both sides by the common denominator to clear denominators."},{"t":"extraneous solution","pos":"noun phrase","ipa":"/ɪkˈstreɪ.ni.əs səˈluː.ʃən/","vi":"nghiệm ngoại lai (loại)","ex":"The value x = 1 is an extraneous solution because it does not satisfy the defined condition."},{"t":"solution","pos":"noun","ipa":"/səˈluː.ʃən/","vi":"nghiệm","ex":"The equation has two solutions: x = −2 and x = 1."},{"t":"no solution","pos":"phrase","ipa":"/nəʊ səˈluː.ʃən/","vi":"vô nghiệm","ex":"Because the candidate value is rejected, the equation has no solution."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"thu gọn","ex":"We can simplify the equation by combining like terms."},{"t":"value","pos":"noun","ipa":"/ˈvæl.juː/","vi":"giá trị","ex":"Substitute the value of x back into the equation to check your solution."}],"dlg":[{"who":"Ms. Alice","text":"Class, what is our first step in solving this equation with variables in the denominator?"},{"who":"Student","text":"We must find the defined condition first to avoid dividing by zero!"},{"who":"Ms. Alice","text":"Perfect! Since x³ − 1 = (x − 1)(x² + x + 1), our defined condition is indeed x is not equal to 1. Now, what's next?"},{"who":"Student","text":"We find the common denominator and then clear denominators!"},{"who":"Ms. Alice","text":"Excellent! We get x = 1 or x = 0.5. But wait, is x = 1 a valid solution?"},{"who":"Student","text":"No! It violates our defined condition, so x = 1 is an extraneous solution. The unique solution is x = 0.5!"}],"extras":[],"note":"Mỗi bài từ Bài 4 trở đi có 15 từ (Bài 1: 20 từ, Bài 2: 12 từ), đúng theo tài liệu gốc."},{"n":5,"en":"INEQUALITIES AND THEIR PROPERTIES","vi":"BẤT ĐẲNG THỨC VÀ TÍNH CHẤT","page":5,"focus":"","cards":[{"t":"inequality","pos":"noun","ipa":"/ˌɪn.ɪˈkwɒl.ə.ti/","vi":"bất đẳng thức","ex":"An inequality is a statement comparing two mathematical expressions."},{"t":"left-hand side","pos":"noun phrase","ipa":"/left hænd saɪd/","vi":"vế trái","ex":"In the inequality 3x + 5 > 12, the left-hand side is 3x + 5."},{"t":"right-hand side","pos":"noun phrase","ipa":"/raɪt hænd saɪd/","vi":"vế phải","ex":"In the inequality a² + 1 > 0, the right-hand side is 0."},{"t":"greater than","pos":"prepositional phrase","ipa":"/ˈɡreɪ.tə ðæn/","vi":"lớn hơn","ex":"The mathematical statement 2024 > 1954 shows that 2024 is greater than 1954."},{"t":"less than","pos":"prepositional phrase","ipa":"/les ðæn/","vi":"nhỏ hơn","ex":"The comparison −34.22 < −27 shows that −34.22 is less than −27."},{"t":"greater than or equal to","pos":"phrase","ipa":"/ˈɡreɪ.tə ðæn ɔːr ˈiː.kwəl tuː/","vi":"lớn hơn hoặc bằng","ex":"To operate an electric motorbike, your age x must be greater than or equal to 16, written as x ≥ 16."},{"t":"less than or equal to","pos":"phrase","ipa":"/les ðæn ɔːr ˈiː.kwəl tuː/","vi":"nhỏ hơn hoặc bằng","ex":"A bus can carry a maximum of 45 people, meaning the number of passengers y is less than or equal to 45."},{"t":"same direction","pos":"noun phrase","ipa":"/seɪm daɪˈrek.ʃən/","vi":"cùng chiều","ex":"The inequalities 1 < 2 and −3 < −2 are in the same direction."},{"t":"opposite direction","pos":"noun phrase","ipa":"/ˈɒp.ə.zɪt daɪˈrek.ʃən/","vi":"ngược chiều","ex":"The inequalities 1 < 2 and −2 > −3 are in the opposite direction."},{"t":"transitive property","pos":"noun phrase","ipa":"/ˈtræn.sə.tɪv ˈprɒp.ə.ti/","vi":"tính chất bắc cầu","ex":"By the transitive property, if a < b and b < c, then we can conclude that a < c."},{"t":"addition property","pos":"noun phrase","ipa":"/əˈdɪʃ.ən ˈprɒp.ə.ti/","vi":"tính chất liên quan đến phép cộng","ex":"Adding the same number to both sides of an inequality preserves its direction."},{"t":"multiplication property","pos":"noun phrase","ipa":"/ˌmʌl.tɪ.plɪˈkeɪ.ʃən ˈprɒp.ə.ti/","vi":"tính chất liên quan đến phép nhân","ex":"According to the multiplication property, multiplying an inequality by a negative number reverses its sign."},{"t":"positive number","pos":"noun phrase","ipa":"/ˈpɒz.ə.tɪv ˈnʌm.bə/","vi":"số dương","ex":"If you multiply an inequality by a positive number, the direction remains unchanged."},{"t":"negative number","pos":"noun phrase","ipa":"/ˈneɡ.ə.tɪv ˈnʌm.bə/","vi":"số âm","ex":"Be careful when multiplying an inequality by a negative number, as you must flip the inequality sign."},{"t":"number line","pos":"noun phrase","ipa":"/ˈnʌm.bə laɪn/","vi":"trục số","ex":"On a number line, a smaller number always lies to the left of a larger number."}],"dlg":[{"who":"Ms. Alice","text":"How can we write an inequality to find the maximum number of students who can join the field trip?"},{"who":"Student","text":"We can represent the total cost as 17,000,000 + 150,000x, which must be less than or equal to 30,000,000!"},{"who":"Ms. Alice","text":"Using the addition property, we subtract 17 from both sides to get 0.15x ≤ 13. What is the next step?"},{"who":"Student","text":"We divide both sides by the positive number 0.15 without changing the direction of the inequality!"},{"who":"Ms. Alice","text":"Excellent calculation! Since x must be an integer, what is our final answer?"},{"who":"Student","text":"The maximum number of students who can join the field trip is exactly 86!"}],"extras":[]},{"n":6,"en":"LINEAR INEQUALITIES IN ONE VARIABLE","vi":"BẤT PHƯƠNG TRÌNH BẬC NHẤT MỘT ẨN","page":6,"focus":"","cards":[{"t":"linear inequality in one variable","pos":"noun phrase","ipa":"/ˈlɪn.i.ə ˌɪn.ɪˈkwɒl.ə.ti ɪn wʌn ˈveə.ri.ə.bəl/","vi":"bất phương trình bậc nhất một ẩn","ex":"An inequality of the form ax + b < 0 is a linear inequality in one variable."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"ẩn số / biến số","ex":"In the inequality 7x + 18 ≤ 100, the letter x is the variable."},{"t":"left-hand side","pos":"noun phrase","ipa":"/left hænd saɪd/","vi":"vế trái","ex":"The left-hand side of the inequality 3x + 8 < 20 is the algebraic expression 3x + 8."},{"t":"right-hand side","pos":"noun phrase","ipa":"/raɪt hænd saɪd/","vi":"vế phải","ex":"The right-hand side of 7x + 18 ≤ 100 is the constant value 100."},{"t":"solution of an inequality","pos":"noun phrase","ipa":"/səˈluː.ʃən əv ən ˌɪn.ɪˈkwɒl.ə.ti/","vi":"nghiệm của bất phương trình","ex":"Since the value x = 2 makes the inequality true, it is a solution of the inequality."},{"t":"solve","pos":"verb","ipa":"/sɒlv/","vi":"giải (bất phương trình)","ex":"To solve an inequality means to find the set of all its solutions."},{"t":"properties of inequalities","pos":"noun phrase","ipa":"/ˈprɒp.ə.tiz əv ˌɪn.ɪˈkwɒl.ə.tiz/","vi":"tính chất của bất đẳng thức","ex":"We apply the properties of inequalities to perform step-by-step transformations."},{"t":"add to both sides","pos":"verb phrase","ipa":"/æd tuː bəʊθ saɪdz/","vi":"cộng vào hai vế","ex":"Add −18 to both sides of the inequality to isolate the term containing the variable."},{"t":"multiply both sides","pos":"verb phrase","ipa":"/ˈmʌl.tɪ.plaɪ bəʊθ saɪdz/","vi":"nhân cả hai vế","ex":"If we multiply both sides of an inequality by a positive number, the direction remains unchanged."},{"t":"divide both sides","pos":"verb phrase","ipa":"/dɪˈvaɪd bəʊθ saɪdz/","vi":"chia cả hai vế","ex":"Divide both sides of 7x ≤ 82 by 7 to find the range of x."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"In the inequality −2x − 4 > 0, the coefficient of the variable is −2."},{"t":"reverse the inequality sign","pos":"verb phrase","ipa":"/rɪˈvɜːs ði ˌɪn.ɪˈkwɒl.ə.ti saɪn/","vi":"đổi chiều dấu bất đẳng thức","ex":"When we multiply or divide by a negative number, we must reverse the inequality sign."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"thu gọn / rút gọn","ex":"Simplify the expressions on each side before solving the inequality."},{"t":"interest rate","pos":"noun phrase","ipa":"/ˈɪn.trəst reɪt/","vi":"lãi suất","ex":"An annual interest rate of 7.4% is applied to her savings deposit."},{"t":"payload","pos":"noun","ipa":"/ˈpeɪ.ləʊd/","vi":"trọng tải","ex":"The total payload of the truck must not exceed 5.25 tonnes."}],"dlg":[{"who":"Ms. Alice","text":"Class, Thanh has 100,000 VND. She buys an 18,000 VND pen and x notebooks, each costing 7,000 VND. How do we write this mathematically?"},{"who":"Student","text":"The total cost must be less than or equal to 100,000, so we set up: 7x + 18 ≤ 100!"},{"who":"Ms. Alice","text":"Excellent! Now we solve it. First, add −18 to both sides, and then we divide both sides by the coefficient 7."},{"who":"Student","text":"We get x ≤ 82 over 7, which is approximately 11.7!"},{"who":"Ms. Alice","text":"Perfect! Since the number of notebooks must be a natural number, what is the maximum number of notebooks she can buy?"},{"who":"Student","text":"She can buy a maximum of 11 notebooks!"}],"extras":[]},{"n":7,"en":"SQUARE ROOTS AND QUADRATIC RADICALS","vi":"CĂN BẬC HAI VÀ CĂN THỨC BẬC HAI","page":7,"focus":"","cards":[{"t":"square root","pos":"noun","ipa":"/skweə ruːt/","vi":"căn bậc hai","ex":"A positive number x has two square roots, which are opposite in sign: 49 has +7 and −7."},{"t":"arithmetic square root","pos":"noun phrase","ipa":"/ˌær.ɪθˈmet.ɪk skweə ruːt/","vi":"căn bậc hai số học","ex":"The arithmetic square root of 81 is written as √81, which equals 9."},{"t":"quadratic radical","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ˈræd.ɪ.kəl/","vi":"căn thức bậc hai","ex":"An algebraic expression containing a variable under a square root is a quadratic radical."},{"t":"radicand","pos":"noun","ipa":"/ˈræd.ɪ.kænd/","vi":"biểu thức dưới dấu căn / biểu thức lấy căn","ex":"In the radical expression √(2x + 1), the polynomial 2x + 1 is the radicand."},{"t":"defined condition","pos":"noun phrase","ipa":"/dɪˈfaɪnd kənˈdɪʃ.ən/","vi":"điều kiện xác định","ex":"To find the defined condition of the radical √(2x + 1), we set the radicand 2x + 1 ≥ 0."},{"t":"non-negative","pos":"adjective","ipa":"/ˌnɒn ˈneɡ.ə.tɪv/","vi":"không âm (≥ 0)","ex":"The radicand under a square root must always be a non-negative value."},{"t":"absolute value","pos":"noun phrase","ipa":"/ˈæb.sə.luːt ˈvæl.juː/","vi":"giá trị tuyệt đối","ex":"Using the identity √(a²) = |a|, we can write the output in terms of its absolute value."},{"t":"identity","pos":"noun","ipa":"/aɪˈden.tə.ti/","vi":"hằng đẳng thức","ex":"The mathematical identity √(A²) = |A| is used to simplify quadratic radicals."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"rút gọn","ex":"We can simplify the expression √(x² − 4x + 4) when we know the value of x is less than 2."},{"t":"square root extraction","pos":"noun phrase","ipa":"/skweə ruːt ɪkˈstræk.ʃən/","vi":"khai phương / phép khai căn bậc hai","ex":"The mathematical process of finding the arithmetic square root of a number is called square root extraction."},{"t":"multiplication","pos":"noun","ipa":"/ˌmʌl.tɪ.plɪˈkeɪ.ʃən/","vi":"phép nhân","ex":"We can use multiplication properties to write √a · √b as √(ab)."},{"t":"division","pos":"noun","ipa":"/dɪˈvɪʒ.ən/","vi":"phép chia","ex":"The division property allows us to write the quotient of two square roots as the root of the quotient."},{"t":"conjugate expression","pos":"noun phrase","ipa":"/ˈkɒn.dʒə.ɡət ɪkˈspreʃ.ən/","vi":"biểu thức liên hợp","ex":"To clear the radical from the denominator, we multiply the fraction by its conjugate expression."},{"t":"hypotenuse","pos":"noun","ipa":"/haɪˈpɒt.ə.njuːs/","vi":"cạnh huyền","ex":"We express the length of the hypotenuse as a quadratic radical: BC = √(AB² + AC²)."},{"t":"kinetic energy","pos":"noun phrase","ipa":"/kɪˈnet.ɪk ˈen.ə.dʒi/","vi":"động năng","ex":"In physics, flying speed is calculated using kinetic energy: v = √(2E/m)."}],"dlg":[{"who":"Ms. Alice","text":"Class, the distance of a falling object is S = 4.9t². How do we calculate the time t to reach the ground?"},{"who":"Student","text":"We can set up the equation: 122.5 = 4.9t²!"},{"who":"Ms. Alice","text":"Excellent! Now we have t² = 25. How do we find the value of time t?"},{"who":"Student","text":"We must perform square root extraction. Since time t must be positive, we find the arithmetic square root!"},{"who":"Ms. Alice","text":"Brilliant! The square root of 25 equals 5. So, what is our final answer?"},{"who":"Student","text":"The object hits the ground after exactly 5 seconds!"}],"extras":[{"title":"Tip","text":"Master these terms to understand and solve problems involving square roots and quadratic radicals in mathematics and real-life situations."}]},{"n":8,"en":"SQUARE ROOT EXTRACTION WITH MULTIPLICATION AND DIVISION","vi":"KHAI CĂN BẬC HAI VỚI PHÉP NHÂN VÀ PHÉP CHIA","page":8,"focus":"","cards":[{"t":"square root","pos":"noun","ipa":"/skweə ruːt/","vi":"căn bậc hai","ex":"The square root of 81 is 9 because 9 squared equals 81."},{"t":"square root extraction","pos":"noun phrase","ipa":"/skweə ruːt ɪkˈstræk.ʃən/","vi":"phép khai căn bậc hai","ex":"Square root extraction is the inverse operation of squaring a non-negative number."},{"t":"multiplication","pos":"noun","ipa":"/ˌmʌl.tɪ.plɪˈkeɪ.ʃən/","vi":"phép nhân","ex":"We can extract the square root of a product by performing multiplication after extracting each root."},{"t":"division","pos":"noun","ipa":"/dɪˈvɪʒ.ən/","vi":"phép chia","ex":"The rule for the square root of a quotient relates square root extraction to division."},{"t":"product","pos":"noun","ipa":"/ˈprɒd.ʌkt/","vi":"tích","ex":"For non-negative expressions A and B, the square root of their product is √(AB)."},{"t":"quotient","pos":"noun","ipa":"/ˈkwəʊ.ʃənt/","vi":"thương","ex":"The square root of the quotient A over B is equal to the quotient of the square roots of A and B."},{"t":"non-negative expression","pos":"noun phrase","ipa":"/ˌnɒn ˈneɡ.ə.tɪv ɪkˈspreʃ.ən/","vi":"biểu thức không âm","ex":"The product rule √A · √B = √(AB) is valid only when A and B are non-negative expressions."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"rút gọn","ex":"We can simplify the expression √(5x) · √(20x) into 10x for any non-negative x."},{"t":"factor","pos":"noun","ipa":"/ˈfæk.tə/","vi":"thừa số / nhân tử","ex":"To extract the square root, we can write the radicand as a product of prime factors."},{"t":"radicand","pos":"noun","ipa":"/ˈræd.ɪ.kænd/","vi":"biểu thức dưới dấu căn / số lấy căn","ex":"In the radical expression √(25a²b²), the product 25a²b² is the radicand."},{"t":"decimal fraction","pos":"noun phrase","ipa":"/ˈdes.ɪ.məl ˈfræk.ʃən/","vi":"phân số thập phân","ex":"To calculate √1.69, we first write 1.69 as a decimal fraction: 169 over 100."},{"t":"ratio","pos":"noun","ipa":"/ˈreɪ.ʃi.əʊ/","vi":"tỉ số","ex":"Find the ratio between the new voltage and the original voltage in the circuit."},{"t":"power","pos":"noun","ipa":"/ˈpaʊ.ə/","vi":"công suất","ex":"In a direct current circuit, the electrical power P is measured in Watts."},{"t":"voltage","pos":"noun","ipa":"/ˈvəʊl.tɪdʒ/","vi":"hiệu điện thế","ex":"We can calculate the voltage U in volts using the formula U = √(PR)."},{"t":"resistance","pos":"noun","ipa":"/rɪˈzɪs.təns/","vi":"điện trở","ex":"The electrical resistance R of the conductor is measured in Ohms."}],"dlg":[{"who":"Ms. Alice","text":"Class! If power P increases 8 times and resistance R decreases 2 times, what is the new voltage U′?"},{"who":"Student","text":"The new voltage expression must be U′ = √(8P · R/2)!"},{"who":"Ms. Alice","text":"Correct! Now let's simplify the radicand inside. What do we get?"},{"who":"Student","text":"8 divided by 2 is 4, so the radicand becomes 4PR. Thus, U′ = √(4PR)!"},{"who":"Ms. Alice","text":"Excellent! How do we extract the square root of this product?"},{"who":"Student","text":"We separate it: U′ = √4 · √(PR) = 2√(PR). The voltage doubles!"}],"extras":[]},{"n":9,"en":"SIMPLE TRANSFORMATIONS AND SIMPLIFICATION OF RADICAL EXPRESSIONS","vi":"BIẾN ĐỔI ĐƠN GIẢN VÀ RÚT GỌN BIỂU THỨC CHỨA CĂN THỨC BẬC HAI","page":9,"focus":"","cards":[{"t":"simple transformation","pos":"noun phrase","ipa":"/ˈsɪm.pəl ˌtræns.fəˈmeɪ.ʃən/","vi":"phép biến đổi đơn giản","ex":"Performing simple transformations helps us simplify algebraic terms with square roots."},{"t":"simplification","pos":"noun","ipa":"/ˌsɪm.plɪ.fɪˈkeɪ.ʃən/","vi":"phép rút gọn / sự rút gọn","ex":"The simplification of radical expressions makes further equations easier to solve."},{"t":"take factors out of a radical","pos":"verb phrase","ipa":"/teɪk ˈfæk.təz aʊt əv ə ˈræd.ɪ.kəl/","vi":"đưa thừa số ra ngoài dấu căn","ex":"We can take factors out of a radical by writing: √(a² · b) = |a|√b."},{"t":"bring factors into a radical","pos":"verb phrase","ipa":"/brɪŋ ˈfæk.təz ˈɪn.tuː ə ˈræd.ɪ.kəl/","vi":"đưa thừa số vào trong dấu căn","ex":"When you bring factors into a radical, remember that a√b = −√(a²b) if a is negative."},{"t":"rationalize the denominator","pos":"verb phrase","ipa":"/ˈræʃ.ən.əl.aɪz ðə dɪˈnɒm.ɪ.neɪ.tə/","vi":"trục căn thức ở mẫu","ex":"Multiply both the numerator and denominator by the conjugate to rationalize the denominator."},{"t":"conjugate expression","pos":"noun phrase","ipa":"/ˈkɒn.dʒə.ɡət ɪkˈspreʃ.ən/","vi":"biểu thức liên hợp","ex":"The conjugate expression of √a + b is √a − b, which helps us remove radicals."},{"t":"radicand","pos":"noun","ipa":"/ˈræd.ɪ.kænd/","vi":"biểu thức lấy căn / biểu thức dưới dấu căn","ex":"In the term √(x² + 1), the algebraic expression x² + 1 is the radicand."},{"t":"similar radicals","pos":"noun phrase","ipa":"/ˈsɪm.ɪ.lə ˈræd.ɪ.kəlz/","vi":"các căn thức đồng dạng","ex":"We can add or subtract similar radicals, such as 3√2 and 5√2, to get 8√2."},{"t":"absolute value","pos":"noun phrase","ipa":"/ˈæb.sə.luːt ˈvæl.juː/","vi":"giá trị tuyệt đối","ex":"The identity √(a²) = |a| ensures we use the absolute value to preserve positive results."},{"t":"eliminate","pos":"verb","ipa":"/ɪˈlɪm.ɪ.neɪt/","vi":"khử / triệt tiêu / loại bỏ","ex":"Our primary goal when transforming algebraic fractions is to simplify and eliminate radical terms."},{"t":"multiply both the numerator and the denominator","pos":"verb phrase","ipa":"/ˈmʌl.tɪ.plaɪ bəʊθ ðə ˈnjuː.mə.reɪ.tə ænd ðə dɪˈnɒm.ɪ.neɪ.tə/","vi":"nhân cả tử và mẫu","ex":"To rationalize 2 over √3, multiply both the numerator and the denominator by √3."},{"t":"non-negative expression","pos":"noun phrase","ipa":"/ˌnɒn ˈneɡ.ə.tɪv ɪkˈspreʃ.ən/","vi":"biểu thức không âm","ex":"The equation √(A²B) = A√B holds true only when B is a non-negative expression."},{"t":"defined condition","pos":"noun phrase","ipa":"/dɪˈfaɪnd kənˈdɪʃ.ən/","vi":"điều kiện xác định (ĐKXĐ)","ex":"Before simplifying any algebraic radical, always state its defined condition."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"rút gọn / thu gọn","ex":"We simplify the radical sum: 2√3 − √75 + 3√27 = 6√3."},{"t":"identity","pos":"noun","ipa":"/aɪˈden.tə.ti/","vi":"hằng đẳng thức","ex":"We can factor polynomials under radicals using the difference of squares identity."}],"dlg":[{"who":"Ms. Alice","text":"Class, how can we simplify this radical expression under the defined condition x > 1?"},{"who":"Student","text":"We can rationalize the denominator by multiplying both top and bottom by the conjugate!"},{"who":"Ms. Alice","text":"That works! But is there a faster way using factorization identities on the numerator?"},{"who":"Student","text":"Yes! x² − 1 = (x − 1)(x + 1), and we can further write x − 1 = (√x − 1)(√x + 1)!"},{"who":"Ms. Alice","text":"Brilliant! Now we can easily eliminate the common factor. What is our final simplified expression?"},{"who":"Student","text":"The factor (√x − 1) cancels out, leaving us with the neat simplified form: P = (x + 1)(√x + 1)!"}],"extras":[]},{"n":10,"en":"CUBE ROOTS AND CUBIC RADICALS","vi":"CĂN BẬC BA VÀ CĂN THỨC BẬC BA","page":10,"focus":"","cards":[{"t":"cube root","pos":"noun","ipa":"/ˈkjuːb ruːt/","vi":"căn bậc ba","ex":"The cube root of a number a is a number x such that x³ = a."},{"t":"cubic radical","pos":"noun phrase","ipa":"/ˈkjuː.bɪk ˈræd.ɪ.kəl/","vi":"căn thức bậc ba","ex":"A cubic radical is an algebraic expression of the form ³√A."},{"t":"index","pos":"noun","ipa":"/ˈɪn.deks/","vi":"chỉ số (của căn)","ex":"In the symbol ³√a, the number 3 is called the index of the radical."},{"t":"cube root extraction","pos":"noun phrase","ipa":"/ˈkjuːb ruːt ɪkˈstræk.ʃən/","vi":"phép khai căn bậc ba / phép khai căn bậc ba số học","ex":"The mathematical operation of finding the cube root of a number is called cube root extraction."},{"t":"volume","pos":"noun","ipa":"/ˈvɒl.juːm/","vi":"thể tích","ex":"If V is the volume of a cube with edge x, then we can write V = x³."},{"t":"cube","pos":"noun","ipa":"/kjuːb/","vi":"hình lập phương / lập phương (lũy thừa 3)","ex":"To find the edge length of a cube, we calculate the cube root of its volume."},{"t":"edge","pos":"noun","ipa":"/edʒ/","vi":"cạnh (của hình khối)","ex":"Let x represent the length of an edge of a cardboard box."},{"t":"algebraic expression","pos":"noun phrase","ipa":"/ˌæl.dʒɪˈbreɪ.ɪk ɪkˈspreʃ.ən/","vi":"biểu thức đại số","ex":"In the cubic radical ³√A, A represents an algebraic expression."},{"t":"value","pos":"noun","ipa":"/ˈvæl.juː/","vi":"giá trị","ex":"Calculate the value of the cubic radical at x = 60."},{"t":"simplify","pos":"verb","ipa":"/ˈsɪm.plɪ.faɪ/","vi":"rút gọn","ex":"Simplify the expression by rewriting the polynomial under the radical: ³√(x³ + 3x² + 3x + 1) = x + 1."},{"t":"identity","pos":"noun","ipa":"/aɪˈden.tə.ti/","vi":"hằng đẳng thức","ex":"We can simplify the cubic radical using the identity ³√(A³) = A."},{"t":"cube of a sum","pos":"noun phrase","ipa":"/kjuːb əv ə sʌm/","vi":"lập phương của một tổng","ex":"Use the cube of a sum formula to factor the polynomial: x³ + 3x² + 3x + 1 = (x + 1)³."},{"t":"cube of a difference","pos":"noun phrase","ipa":"/kjuːb əv ə ˈdɪf.ər.əns/","vi":"lập phương của một hiệu","ex":"The expression x³ − 3x² + 3x − 1 can be rewritten as the cube of a difference: (x − 1)³."},{"t":"real number","pos":"noun phrase","ipa":"/rɪəl ˈnʌm.bə/","vi":"số thực","ex":"Unlike square roots, every real number has a unique cube root."},{"t":"unique","pos":"adjective","ipa":"/juːˈniːk/","vi":"duy nhất","ex":"Every real number has a unique cube root, whether it is positive, zero, or negative."}],"dlg":[{"who":"Ms. Alice","text":"Class, we need to make a cardboard cube box with no lid, having a volume of 216 dm³. How do we find its edge length x?"},{"who":"Student","text":"Since V = x³, we can write the equation: x³ = 216!"},{"who":"Ms. Alice","text":"Perfect! Now we find its unique cube root."},{"who":"Student","text":"We extract the cube root: x = ³√216. Since 6³ = 216, the edge length is exactly 6 dm!"},{"who":"Ms. Alice","text":"Great job! Since the box has no lid, it has only 5 faces. What is the total area of cardboard needed?"},{"who":"Student","text":"Each face is a square of area 6² = 36 dm². Thus, the total area is 5 × 36 = 180 dm²!"}],"extras":[]},{"n":11,"en":"TRIGONOMETRIC RATIOS OF AN ACUTE ANGLE","vi":"TỈ SỐ LƯỢNG GIÁC CỦA GÓC NHỌN","page":11,"focus":"","cards":[{"t":"acute angle","pos":"noun phrase","ipa":"/əˈkjuːt ˈæŋ.ɡəl/","vi":"góc nhọn","ex":"In a right-angled triangle, the two non-right angles are always acute angles."},{"t":"opposite side","pos":"noun phrase","ipa":"/ˈɒp.ə.zɪt saɪd/","vi":"cạnh đối","ex":"In triangle ABC right-angled at A, side AC is the opposite side of angle B."},{"t":"adjacent side","pos":"noun phrase","ipa":"/əˈdʒeɪ.sənt saɪd/","vi":"cạnh kề","ex":"Side AB is the adjacent side of the acute angle B in the right triangle ABC."},{"t":"hypotenuse","pos":"noun","ipa":"/haɪˈpɒt.ə.njuːs/","vi":"cạnh huyền","ex":"The hypotenuse is always the longest side of a right-angled triangle and lies opposite the right angle."},{"t":"trigonometric ratio","pos":"noun phrase","ipa":"/ˌtrɪɡ.ə.nəˈmet.rɪk ˈreɪ.ʃi.əʊ/","vi":"tỉ số lượng giác","ex":"The trigonometric ratios of an acute angle depend only on the measure of the angle, not the size of the triangle."},{"t":"sine","pos":"noun","ipa":"/saɪn/","vi":"sin","ex":"The sine of angle α is defined as the opposite side to the hypotenuse: sin α = AC / BC."},{"t":"cosine","pos":"noun","ipa":"/ˈkəʊ.saɪn/","vi":"côsin","ex":"The cosine of an acute angle is the ratio of its adjacent side to the hypotenuse: cos α = AB / BC."},{"t":"tangent","pos":"noun","ipa":"/ˈtæn.dʒənt/","vi":"tang","ex":"The tangent of angle B is the ratio of the opposite side to the adjacent side: tan α = AC / AB."},{"t":"cotangent","pos":"noun","ipa":"/ˌkəʊˈtæn.dʒənt/","vi":"côtang","ex":"The cotangent of an angle is the reciprocal of its tangent: cot α = 1 / tan α."},{"t":"complementary angles","pos":"noun phrase","ipa":"/ˌkɒm.plɪˈmen.tər.i ˈæŋ.ɡəlz/","vi":"các góc phụ nhau","ex":"If two angles are complementary angles, the sine of one angle equals the cosine of the other."},{"t":"trigonometric value","pos":"noun phrase","ipa":"/ˌtrɪɡ.ə.nəˈmet.rɪk ˈvæl.juː/","vi":"giá trị lượng giác","ex":"We can find the exact trigonometric value of special angles such as 30, 45, or 60 degrees."},{"t":"degree","pos":"noun","ipa":"/dɪˈɡriː/","vi":"độ (đơn vị đo góc)","ex":"An acute angle has a measure greater than 0 degrees but less than 90 degrees."},{"t":"minute","pos":"noun","ipa":"/ˈmɪn.ɪt/","vi":"phút (đơn vị đo góc)","ex":"There are exactly 60 minutes in one degree of an angle, used for precise measurements."},{"t":"second","pos":"noun","ipa":"/ˈsek.ənd/","vi":"giây (đơn vị đo góc)","ex":"One minute of an angle is further subdivided into 60 seconds."},{"t":"slope angle","pos":"noun phrase","ipa":"/sləʊp ˈæŋ.ɡəl/","vi":"góc dốc","ex":"We can calculate the slope angle of the road ramp to see if it is safe for wheelchair users."}],"dlg":[{"who":"Ms. Alice","text":"Class, our building has a wheelchair ramp that is 4 meters long and 0.4 meters high. What is the sine of its slope angle α?"},{"who":"Student","text":"Since sine is opposite divided by hypotenuse, sin α = 0.4 over 4, which is 0.1!"},{"who":"Ms. Alice","text":"Excellent! Now, how can we find the measure of the slope angle α in degrees and minutes?"},{"who":"Student","text":"We can use our handheld calculator to find the angle when sin α = 0.1. We get α is approximately 5 degrees 44 minutes!"},{"who":"Ms. Alice","text":"Brilliant! Standard building regulations require the wheelchair slope angle to be less than 6 degrees. Is our ramp safe?"},{"who":"Student","text":"Yes, Ms. Alice! Since 5 degrees 44 minutes is less than 6 degrees, our ramp is perfectly safe and complies with the rules!"}],"extras":[{"title":"Tip","text":"Master these terms to understand and solve problems involving trigonometric ratios in mathematics and real-life situations."}]},{"n":12,"en":"RELATIONS BETWEEN SIDES AND ANGLES IN A RIGHT TRIANGLE","vi":"MỘT SỐ HỆ THỨC GIỮA CẠNH VÀ GÓC TRONG TAM GIÁC VUÔNG","page":12,"focus":"","cards":[{"t":"right triangle","pos":"noun","ipa":"/raɪt ˈtraɪ.æŋ.ɡəl/","vi":"tam giác vuông","ex":"In a right triangle, the relationships between the sides and angles are defined by trigonometric ratios."},{"t":"hypotenuse","pos":"noun","ipa":"/haɪˈpɒt.ə.njuːs/","vi":"cạnh huyền","ex":"Each leg is equal to the hypotenuse multiplied by the sine of the opposite angle."},{"t":"opposite side","pos":"noun phrase","ipa":"/ˈɒp.ə.zɪt saɪd/","vi":"cạnh đối","ex":"For the acute angle B, the opposite side is AC, which can be found using the formula b = a · sin B."},{"t":"adjacent side","pos":"noun phrase","ipa":"/əˈdʒeɪ.sənt saɪd/","vi":"cạnh kề","ex":"For the acute angle B, the adjacent side is AB, which can be calculated using the formula c = a · cos B."},{"t":"acute angle","pos":"noun phrase","ipa":"/əˈkjuːt ˈæŋ.ɡəl/","vi":"góc nhọn","ex":"The angle of elevation of the plane's ascent is an acute angle measuring thirty degrees."},{"t":"relation","pos":"noun","ipa":"/rɪˈleɪ.ʃən/","vi":"hệ thức","ex":"We use the mathematical relations in a right triangle to calculate heights and distances without direct measurement."},{"t":"sine","pos":"noun","ipa":"/saɪn/","vi":"sin","ex":"To find side b, multiply the hypotenuse a by the sine of the opposite angle B."},{"t":"cosine","pos":"noun","ipa":"/ˈkəʊ.saɪn/","vi":"côsin","ex":"To find side c, multiply the hypotenuse a by the cosine of the adjacent angle B."},{"t":"tangent","pos":"noun","ipa":"/ˈtæn.dʒənt/","vi":"tang","ex":"Each leg is equal to the other leg multiplied by the tangent of the opposite angle."},{"t":"cotangent","pos":"noun","ipa":"/ˌkəʊˈtæn.dʒənt/","vi":"côtang","ex":"Each leg is equal to the other leg multiplied by the cotangent of the adjacent angle."},{"t":"solve a right triangle","pos":"verb phrase","ipa":"/sɒlv ə raɪt ˈtraɪ.æŋ.ɡəl/","vi":"giải tam giác vuông","ex":"To solve a right triangle means to find all its unknown sides and angles when two elements are given."},{"t":"clinometer","pos":"noun","ipa":"/klaɪˈnɒm.ɪ.tə/","vi":"giác kế","ex":"The surveyor placed the clinometer vertically at point M to measure the angle of elevation of the tower."},{"t":"angle of elevation","pos":"noun phrase","ipa":"/ˈæŋ.ɡəl əv ˌel.ɪˈveɪ.ʃən/","vi":"góc nâng / góc nghiêng","ex":"The sun's rays strike the ground at an angle of elevation of approximately thirty-four degrees."},{"t":"shadow","pos":"noun","ipa":"/ˈʃæd.əʊ/","vi":"bóng / bóng nắng","ex":"The shadow of a tower on the ground is 8.6 meters long when the elevation angle is 34 degrees."},{"t":"line of sight","pos":"noun phrase","ipa":"/laɪn əv saɪt/","vi":"đường ngắm / hướng nhìn","ex":"Rotate the sighting tube of the clinometer so that the top of the castle is along your line of sight."}],"dlg":[{"who":"Ms. Alice","text":"Class, the shadow of a tower is 8.6 meters long, and the angle of elevation of the sun is 34 degrees. How do we find its height?"},{"who":"Student","text":"We can model this as a right triangle with an adjacent side of 8.6 meters and an acute angle of 34 degrees!"},{"who":"Ms. Alice","text":"Exactly! Which relation between sides and angles should we use to find the opposite side?"},{"who":"Student","text":"We use the tangent formula: opposite side equals adjacent side times tangent, so h = 8.6 · tan 34 degrees!"},{"who":"Ms. Alice","text":"Perfect! Since tan 34 degrees is approximately 0.6745, what is our final height?"},{"who":"Student","text":"The height of the tower is 8.6 times 0.6745, which is approximately 5.8 meters, rounded to 6 meters!"}],"extras":[]},{"n":13,"en":"INTRODUCTION TO CIRCLES","vi":"MỞ ĐẦU VỀ ĐƯỜNG TRÒN","page":13,"focus":"","cards":[{"t":"circle","pos":"noun","ipa":"/ˈsɜː.kəl/","vi":"đường tròn","ex":"A circle with center O and radius R is denoted as (O; R)."},{"t":"center","pos":"noun","ipa":"/ˈsen.tə/","vi":"tâm (đường tròn)","ex":"The distance from the center of the circle to any point on its boundary is always constant."},{"t":"radius","pos":"noun, plural: radii","ipa":"/ˈreɪ.di.əs/","vi":"bán kính","ex":"The radius of this circle is exactly 3 centimeters."},{"t":"diameter","pos":"noun","ipa":"/daɪˈæm.ɪ.tə/","vi":"đường kính","ex":"A diameter of a circle is twice its radius and must pass through the center."},{"t":"circular region","pos":"noun phrase","ipa":"/ˈsɜː.kjə.lə ˈriː.dʒən/","vi":"hình tròn","ex":"A circular region consists of all points lying on and inside the circle."},{"t":"interior point","pos":"noun phrase","ipa":"/ɪnˈtɪə.ri.ə pɔɪnt/","vi":"điểm nằm trong (đường tròn)","ex":"Point C is an interior point of the circle (O; R) because the distance OC is less than the radius R."},{"t":"exterior point","pos":"noun phrase","ipa":"/ɪkˈstɪə.ri.ə pɔɪnt/","vi":"điểm nằm ngoài (đường tròn)","ex":"Point B is an exterior point of the circle because the distance OB is greater than R."},{"t":"point on the circle","pos":"noun phrase","ipa":"/pɔɪnt ɒn ðə ˈsɜː.kəl/","vi":"điểm nằm trên đường tròn","ex":"If point A is a point on the circle (O; R), then the segment OA is equal to the radius R."},{"t":"center of symmetry","pos":"noun phrase","ipa":"/ˈsen.tə əv ˈsɪm.ə.tri/","vi":"tâm đối xứng","ex":"A circle has exactly one center of symmetry, which is the center of the circle."},{"t":"axis of symmetry","pos":"noun phrase","ipa":"/ˈæk.sɪs əv ˈsɪm.ə.tri/","vi":"trục đối xứng","ex":"Each line passing through the center of a circle is an axis of symmetry of that circle."},{"t":"central symmetry","pos":"noun phrase","ipa":"/ˈsen.trəl ˈsɪm.ə.tri/","vi":"đối xứng tâm","ex":"Two points are symmetric with respect to a point O under central symmetry."},{"t":"reflectional symmetry","pos":"noun phrase","ipa":"/rɪˈflek.ʃən.əl ˈsɪm.ə.tri/","vi":"đối xứng trục","ex":"A circle exhibits reflectional symmetry across any diameter line."},{"t":"perpendicular bisector","pos":"noun phrase","ipa":"/ˌpɜː.pənˈdɪk.jə.lə baɪˈsek.tə/","vi":"đường trung trực","ex":"The perpendicular bisector of a segment consists of all points equidistant from its endpoints."},{"t":"midpoint","pos":"noun","ipa":"/ˈmɪd.pɔɪnt/","vi":"trung điểm","ex":"If O is the midpoint of the diameter AB, then the segment OA equals OB."},{"t":"circumference","pos":"noun","ipa":"/səˈkʌm.fər.əns/","vi":"chu vi đường tròn","ex":"The circumference of a circle represents the total boundary length of the circle."}],"dlg":[{"who":"Ms. Alice","text":"Class, we have a circular piece of paper with no center marked. How can we find its center?"},{"who":"Student","text":"Can we fold it to find a line of symmetry?"},{"who":"Ms. Alice","text":"Excellent! When we fold it in half, the folded crease is an axis of symmetry, which is a diameter of the circle!"},{"who":"Student","text":"Ah, so any diameter line is a line of symmetry!"},{"who":"Ms. Alice","text":"Perfect! Now we fold it in half again along another direction. What do you see at their intersection?"},{"who":"Student","text":"The intersection of the two diameters is the center of our circle!"}],"extras":[]},{"n":14,"en":"ARCS AND CHORDS OF A CIRCLE","vi":"CUNG VÀ DÂY CỦA MỘT ĐƯỜNG TRÒN","page":14,"focus":"","cards":[{"t":"arc","pos":"noun","ipa":"/ɑːk/","vi":"cung / cung tròn","ex":"The two points A and B on the circle divide it into two parts, each of which is an arc."},{"t":"chord","pos":"noun","ipa":"/kɔːd/","vi":"dây cung / dây","ex":"A line segment connecting any two points on a circle is called a chord."},{"t":"diameter","pos":"noun","ipa":"/daɪˈæm.ɪ.tə/","vi":"đường kính","ex":"A diameter is a chord that passes through the center of the circle, and it is the longest chord."},{"t":"semicircle","pos":"noun","ipa":"/ˈsem.iˌsɜː.kəl/","vi":"nửa đường tròn","ex":"When the chord is a diameter, it divides the circle into two equal arcs, each called a semicircle."},{"t":"central angle","pos":"noun phrase","ipa":"/ˈsen.trəl ˈæŋ.ɡəl/","vi":"góc ở tâm","ex":"An angle whose vertex is the center of a circle is called a central angle."},{"t":"intercepted arc","pos":"noun phrase","ipa":"/ˌɪn.təˈsep.tɪd ɑːk/","vi":"cung bị chắn","ex":"We say that the central angle AOB intercepts the arc AB, which is called the intercepted arc."},{"t":"minor arc","pos":"noun phrase","ipa":"/ˈmaɪ.nə ɑːk/","vi":"cung nhỏ","ex":"When the central angle is not a straight angle, the arc lying inside the angle is the minor arc."},{"t":"major arc","pos":"noun phrase","ipa":"/ˈmeɪ.dʒə ɑːk/","vi":"cung lớn","ex":"The remaining arc of the circle that lies outside the central angle is called the major arc."},{"t":"arc measure","pos":"noun phrase","ipa":"/ɑːk ˈmeʒ.ə/","vi":"số đo cung","ex":"The arc measure of a minor arc is defined to be equal to the measure of its central angle."},{"t":"endpoint","pos":"noun","ipa":"/ˈend.pɔɪnt/","vi":"đầu mút / mút","ex":"The two points A and B on the circle are called the endpoints of the arc AB."},{"t":"equal arcs","pos":"noun phrase","ipa":"/ˈiː.kwəl ɑːks/","vi":"các cung bằng nhau","ex":"Two arcs on a circle are called equal arcs if they have the same arc measure."},{"t":"center","pos":"noun","ipa":"/ˈsen.tə/","vi":"tâm đường tròn","ex":"The center of a circle is the fixed point from which all points on the circumference are equidistant."},{"t":"radius","pos":"noun","ipa":"/ˈreɪ.di.əs/","vi":"bán kính","ex":"The radius is the distance from the center of the circle to any point on the circle."},{"t":"distance","pos":"noun","ipa":"/ˈdɪs.təns/","vi":"khoảng cách (từ tâm)","ex":"We can calculate the distance from the center of the circle to a chord using the Pythagorean theorem."},{"t":"perpendicular","pos":"adjective","ipa":"/ˌpɜː.pənˈdɪk.jə.lə/","vi":"vuông góc","ex":"A diameter that is perpendicular to a chord bisects the chord at its midpoint."}],"dlg":[{"who":"Ms. Alice","text":"Class, if we have a central angle AOB measuring 120 degrees, what is the arc measure of the minor arc AB?"},{"who":"Student","text":"The arc measure of the minor arc AB is also 120 degrees!"},{"who":"Ms. Alice","text":"Wonderful! Now, who can tell me how to find the measure of the major arc AmB?"},{"who":"Student","text":"We subtract the minor arc from 360 degrees! So, the major arc measure is 360 − 120 = 240 degrees!"},{"who":"Ms. Alice","text":"Exactly! Now look at this diameter CD and chord EF. Which chord is the longest in any circle?"},{"who":"Student","text":"The diameter is always the longest chord! So, diameter CD is definitely longer than chord EF."}],"extras":[]},{"n":15,"en":"ARC LENGTH, AREA OF A CIRCULAR SECTOR AND AN ANNULUS","vi":"ĐỘ DÀI CUNG TRÒN, DIỆN TÍCH HÌNH QUẠT TRÒN VÀ HÌNH VÀNH KHUYÊN","page":15,"focus":"","cards":[{"t":"arc length","pos":"noun phrase","ipa":"/ɑːk leŋθ/","vi":"độ dài cung tròn","ex":"Calculate the arc length of a 120-degree arc in a circle of radius 3 cm."},{"t":"circular arc","pos":"noun phrase","ipa":"/ˈsɜː.kjə.lə ɑːk/","vi":"cung tròn","ex":"A circular arc is a portion of the circumference of a circle."},{"t":"circumference","pos":"noun","ipa":"/səˈkʌm.fər.əns/","vi":"chu vi đường tròn","ex":"The circumference of a circle of radius R is calculated as C = 2πR."},{"t":"radius","pos":"noun","ipa":"/ˈreɪ.di.əs/","vi":"bán kính","ex":"The radius of the wheel is 32.5 centimeters."},{"t":"diameter","pos":"noun","ipa":"/daɪˈæm.ɪ.tə/","vi":"đường kính","ex":"The bicycle wheel has a diameter of 650 mm."},{"t":"circular sector","pos":"noun phrase","ipa":"/ˈsɜː.kjə.lə ˈsek.tə/","vi":"hình quạt tròn","ex":"A slice of a pizza has the shape of a circular sector."},{"t":"annulus","pos":"noun","ipa":"/ˈæn.jə.ləs/","vi":"hình vành khuyên / hình vành khăn","ex":"An annulus is the region bounded by two concentric circles of different radii."},{"t":"concentric circles","pos":"noun phrase","ipa":"/kənˈsen.trɪk ˈsɜː.kəlz/","vi":"hai đường tròn đồng tâm","ex":"Concentric circles share the same center but have different radii."},{"t":"area of a circle","pos":"noun phrase","ipa":"/ˈeə.ri.ə əv ə ˈsɜː.kəl/","vi":"diện tích hình tròn","ex":"The area of a circle with radius R is S = πR²."},{"t":"area of a circular sector","pos":"noun phrase","ipa":"/ˈeə.ri.ə əv ə ˈsɜː.kjə.lə ˈsek.tə/","vi":"diện tích hình quạt tròn","ex":"The area of a circular sector can be found using the formula S = (n/360) · πR²."},{"t":"area of an annulus","pos":"noun phrase","ipa":"/ˈeə.ri.ə əv ən ˈæn.jə.ləs/","vi":"diện tích hình vành khuyên","ex":"The area of an annulus is given by the formula S = π(R² − r²)."},{"t":"central angle","pos":"noun phrase","ipa":"/ˈsen.trəl ˈæŋ.ɡəl/","vi":"góc ở tâm","ex":"A central angle is an angle whose vertex is the center O of the circle."},{"t":"pi constant","pos":"noun phrase","ipa":"/paɪ ˈkɒn.stənt/","vi":"hằng số pi (π)","ex":"In practical calculations, we often approximate the pi constant as 3.14."},{"t":"rotation","pos":"noun","ipa":"/rəʊˈteɪ.ʃən/","vi":"vòng quay / sự quay","ex":"One rotation of the pedal causes the bicycle wheel to spin 3.3 times."},{"t":"distance traveled","pos":"noun phrase","ipa":"/ˈdɪs.təns ˈtræv.əld/","vi":"quãng đường di chuyển","ex":"Calculate the distance traveled by the bicycle after 10 full rotations."}],"dlg":[{"who":"Ms. Alice","text":"Class! Let's calculate the distance traveled by a bicycle. First, what is the circumference of its wheel with diameter 650 mm?"},{"who":"Student","text":"The circumference is C = π · d = 3.14 · 650 = 2041 mm, which is 2.041 meters!"},{"who":"Ms. Alice","text":"Excellent! When the pedal rotates 1 full round, the wheel rotates 3.3 rounds. How far does the bicycle travel per pedal rotation?"},{"who":"Student","text":"It travels 3.3 times the circumference, which is 3.3 · 2.041, approximately 6.735 meters!"},{"who":"Ms. Alice","text":"Brilliant! So if a cyclist pedals 10 continuous rounds, what is the total distance traveled?"},{"who":"Student","text":"We multiply by 10, so the total distance is approximately 67.35 meters!"}],"extras":[{"title":"Tip","text":"Master these terms and formulas to solve problems about arc length, areas of circular regions, and real-life applications."}]},{"n":16,"en":"RELATIVE POSITIONS OF A LINE AND A CIRCLE","vi":"VỊ TRÍ TƯƠNG ĐỐI CỦA ĐƯỜNG THẲNG VÀ ĐƯỜNG TRÒN","page":16,"focus":"","cards":[{"t":"relative position","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv pəˈzɪʃ.ən/","vi":"vị trí tương đối","ex":"We will study three relative positions of a line and a circle: intersecting, touching, and non-intersecting."},{"t":"intersect","pos":"verb","ipa":"/ˌɪn.təˈsekt/","vi":"cắt nhau","ex":"A line and a circle intersect if they have exactly two common points."},{"t":"touch","pos":"verb","ipa":"/tʌtʃ/","vi":"tiếp xúc nhau","ex":"The line and the circle touch each other when the distance from the center to the line equals the radius."},{"t":"non-intersecting","pos":"adjective","ipa":"/ˌnɒn.ɪn.təˈsek.tɪŋ/","vi":"không giao nhau / không cắt nhau","ex":"If the distance d is greater than the radius R, the line and the circle are non-intersecting."},{"t":"tangent line","pos":"noun phrase","ipa":"/ˈtæn.dʒənt laɪn/","vi":"tiếp tuyến","ex":"A line that has only one common point with a circle is called a tangent line."},{"t":"point of tangency","pos":"noun phrase","ipa":"/pɔɪnt əv ˈtæn.dʒən.si/","vi":"tiếp điểm","ex":"Point H is the point of tangency where the line touches the circle."},{"t":"distance","pos":"noun","ipa":"/ˈdɪs.təns/","vi":"khoảng cách (từ tâm)","ex":"Let d be the distance from the center O of the circle to the line a."},{"t":"radius","pos":"noun","ipa":"/ˈreɪ.di.əs/","vi":"bán kính","ex":"The circle has a radius R of 4 centimeters."},{"t":"perpendicular","pos":"adjective","ipa":"/ˌpɜː.pənˈdɪk.jə.lə/","vi":"vuông góc","ex":"If a line is tangent to a circle, then it is perpendicular to the radius at the point of tangency."},{"t":"recognition sign","pos":"noun phrase","ipa":"/ˌrek.əɡˈnɪʃ.ən saɪn/","vi":"dấu hiệu nhận biết","ex":"We use the recognition sign to prove that a given line is indeed a tangent to the circle."},{"t":"intersecting tangents","pos":"noun phrase","ipa":"/ˌɪn.təˈsek.tɪŋ ˈtæn.dʒənts/","vi":"các tiếp tuyến cắt nhau","ex":"The properties of two intersecting tangents show that PA equals PB."},{"t":"angle bisector","pos":"noun phrase","ipa":"/ˈæŋ.ɡəl baɪˈsek.tə/","vi":"tia phân giác","ex":"The line segment connecting the external point to the center is the angle bisector of angle APB."},{"t":"perpendicular bisector","pos":"noun phrase","ipa":"/ˌpɜː.pənˈdɪk.jə.lə baɪˈsek.tə/","vi":"đường trung trực","ex":"The segment OP is the perpendicular bisector of the chord AB."},{"t":"center","pos":"noun","ipa":"/ˈsen.tə/","vi":"tâm đường tròn","ex":"We measure the distance from the center O to the straight line."},{"t":"prove","pos":"verb","ipa":"/pruːv/","vi":"chứng minh","ex":"We can prove that the line is tangent to the circle by showing that d = R."}],"dlg":[{"who":"Ms. Alice","text":"Class, if we toss a coin of radius R = 1 cm onto paper with parallel lines spaced 2 cm apart, what happens?"},{"who":"Student","text":"The coin behaves like a circle and the lines are straight lines!"},{"who":"Ms. Alice","text":"Perfect! Can the coin intersect two lines at the same time?"},{"who":"Student","text":"No! Since the distance between the lines is 2 cm, and the coin's diameter is 2R = 2 cm, it's impossible!"},{"who":"Ms. Alice","text":"Excellent reasoning! So what are the only possible relative positions?"},{"who":"Student","text":"The coin can only touch one line, or not intersect any line at all!"}],"extras":[{"title":"Relative positions","text":"d < R: intersecting. d = R: touching (tangent). d > R: non-intersecting."}]},{"n":17,"en":"RELATIVE POSITIONS OF TWO CIRCLES","vi":"VỊ TRÍ TƯƠNG ĐỐI CỦA HAI ĐƯỜNG TRÒN","page":17,"focus":"","cards":[{"t":"intersecting circles","pos":"noun phrase","ipa":"/ˌɪn.təˈsek.tɪŋ ˈsɜː.kəlz/","vi":"hai đường tròn cắt nhau","ex":"If the center distance OO′ satisfies R − r < OO′ < R + r, they are intersecting circles."},{"t":"tangent circles","pos":"noun phrase","ipa":"/ˈtæn.dʒənt ˈsɜː.kəlz/","vi":"hai đường tròn tiếp xúc nhau","ex":"Tangent circles have exactly one common point, which is called the point of tangency."},{"t":"non-intersecting circles","pos":"noun phrase","ipa":"/ˌnɒn.ɪn.təˈsek.tɪŋ ˈsɜː.kəlz/","vi":"hai đường tròn không giao nhau","ex":"Two circles with no common points at all are classified as non-intersecting circles."},{"t":"point of intersection","pos":"noun phrase","ipa":"/pɔɪnt əv ˌɪn.təˈsek.ʃən/","vi":"giao điểm","ex":"The intersecting circles have exactly two points of intersection, labeled A and B."},{"t":"point of tangency","pos":"noun phrase","ipa":"/pɔɪnt əv ˈtæn.dʒən.si/","vi":"tiếp điểm","ex":"When two circles touch, the point of tangency is collinear with their centers O and O′."},{"t":"externally tangent","pos":"adjective phrase","ipa":"/ɪkˈstɜː.nəl.i ˈtæn.dʒənt/","vi":"tiếp xúc ngoài","ex":"Two circles are externally tangent if their center distance equals the sum of their radii: OO′ = R + r."},{"t":"internally tangent","pos":"adjective phrase","ipa":"/ɪnˈtɜː.nəl.i ˈtæn.dʒənt/","vi":"tiếp xúc trong","ex":"Two circles are internally tangent if the center distance equals the difference of their radii: OO′ = R − r."},{"t":"external to each other","pos":"phrase","ipa":"/ɪkˈstɜː.nəl tuː iːtʃ ˈʌð.ə/","vi":"ngoài nhau / ở ngoài nhau","ex":"When OO′ > R + r, the two circles are external to each other and have no points in common."},{"t":"one containing the other","pos":"phrase","ipa":"/wʌn kənˈteɪ.nɪŋ ði ˈʌð.ə/","vi":"đựng nhau / đường tròn này đựng đường tròn kia","ex":"If OO′ < R − r, the circles do not intersect, with one containing the other."},{"t":"concentric circles","pos":"noun phrase","ipa":"/kənˈsen.trɪk ˈsɜː.kəlz/","vi":"hai đường tròn đồng tâm","ex":"Concentric circles share the same center point, meaning OO′ = 0."},{"t":"center distance","pos":"noun phrase","ipa":"/ˈsen.tə ˈdɪs.təns/","vi":"khoảng cách giữa hai tâm / đoạn nối tâm","ex":"We can determine their relative position by comparing the center distance OO′ with the radii R and r."},{"t":"collinear","pos":"adjective","ipa":"/kəʊˈlɪn.i.ə/","vi":"thẳng hàng","ex":"The center points O, O′ and the point of tangency are collinear."},{"t":"common tangent","pos":"noun phrase","ipa":"/ˈkɒm.ən ˈtæn.dʒənt/","vi":"tiếp tuyến chung","ex":"A straight line that is tangent to both circles at the same time is a common tangent."},{"t":"line of centers","pos":"noun phrase","ipa":"/laɪn əv ˈsen.təz/","vi":"đường nối tâm","ex":"The line of centers OO′ is the axis of symmetry of the figure formed by two circles."},{"t":"common chord","pos":"noun phrase","ipa":"/ˈkɒm.ən kɔːd/","vi":"dây chung","ex":"The common chord of two intersecting circles is perpendicular to their line of centers."}],"dlg":[{"who":"Ms. Alice","text":"Class, during a partial solar eclipse, the Sun and Moon boundaries overlap. What is their relative position?"},{"who":"Student","text":"They have exactly two common points, so they are intersecting circles!"},{"who":"Ms. Alice","text":"Perfect! Now, what about when the Moon is fully inside the Sun but touches its edge at exactly one point?"},{"who":"Student","text":"That represents internally tangent circles, where OO′ = R − r!"},{"who":"Ms. Alice","text":"Brilliant! What about an annular eclipse where they share the exact same center?"},{"who":"Student","text":"They are concentric circles! The center distance OO′ is zero!"}],"extras":[]},{"n":18,"en":"THE FUNCTION y = ax² (a ≠ 0) AND ITS GRAPH","vi":"HÀM SỐ y = ax² (a ≠ 0) VÀ ĐỒ THỊ","page":18,"focus":"","cards":[{"t":"quadratic function","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ˈfʌŋk.ʃən/","vi":"hàm số bậc hai","ex":"The area of a circle is a quadratic function of its radius, represented by S = πr²."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"In the quadratic function y = −3x², the coefficient of x² is −3."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"biến số","ex":"The variable x represents the independent input, and y is the dependent variable."},{"t":"table of values","pos":"noun phrase","ipa":"/ˈteɪ.bəl əv ˈvæl.juːz/","vi":"bảng giá trị","ex":"We need to complete a table of values before plotting the graph of y = 2x²."},{"t":"graph","pos":"noun","ipa":"/ɡrɑːf/","vi":"đồ thị","ex":"The graph of y = ax² is a smooth curve that always passes through the origin."},{"t":"coordinate plane","pos":"noun phrase","ipa":"/kəʊˈɔː.dɪ.nət pleɪn/","vi":"mặt phẳng tọa độ","ex":"Plot the quadratic coordinate points on a two-dimensional coordinate plane."},{"t":"origin","pos":"noun","ipa":"/ˈɒr.ɪ.dʒɪn/","vi":"gốc tọa độ","ex":"The graph of y = ax² always has its vertex at the origin O(0; 0)."},{"t":"curve","pos":"noun","ipa":"/kɜːv/","vi":"đường cong","ex":"The graph of a quadratic function is not a straight line, but a continuous curve."},{"t":"parabola","pos":"noun","ipa":"/pəˈræb.ə.lə/","vi":"đường parabol","ex":"The graph of the quadratic function y = ax² (a ≠ 0) is a parabola."},{"t":"vertex","pos":"noun","ipa":"/ˈvɜː.teks/","vi":"đỉnh (của parabol)","ex":"The vertex of the parabola y = 2x² is at the origin O(0; 0)."},{"t":"axis of symmetry","pos":"noun phrase","ipa":"/ˈæk.sɪs əv ˈsɪm.ə.tri/","vi":"trục đối xứng","ex":"The vertical y-axis is the axis of symmetry of the parabola y = ax²."},{"t":"symmetric","pos":"adjective","ipa":"/sɪˈmet.rɪk/","vi":"đối xứng","ex":"Two points A(x; y) and A′(−x; y) on the parabola are symmetric with respect to the y-axis."},{"t":"x-axis","pos":"noun phrase","ipa":"/ˈeks æk.sɪs/","vi":"trục hoành","ex":"If a > 0, the entire parabola lies above the x-axis, except for its vertex."},{"t":"y-axis","pos":"noun phrase","ipa":"/ˈwaɪ æk.sɪs/","vi":"trục tung","ex":"The vertical y-axis divides the quadratic graph into two identical parts."},{"t":"highest point","pos":"noun phrase","ipa":"/ˈhaɪ.ɪst pɔɪnt/","vi":"điểm cao nhất","ex":"When a < 0, the origin is the highest point of the parabola."},{"t":"lowest point","pos":"noun phrase","ipa":"/ˈləʊ.ɪst pɔɪnt/","vi":"điểm thấp nhất","ex":"When a > 0, the origin is the lowest point of the parabola."},{"t":"open upward","pos":"verb phrase","ipa":"/ˈəʊ.pən ˈʌp.wəd/","vi":"mở rộng lên phía trên","ex":"Since the coefficient a is positive, the parabola opens upward."},{"t":"open downward","pos":"verb phrase","ipa":"/ˈəʊ.pən ˈdaʊn.wəd/","vi":"mở rộng xuống phía dưới","ex":"Since the coefficient a is negative, the parabola opens downward."},{"t":"coordinates","pos":"noun, plural","ipa":"/kəʊˈɔː.dɪ.nəts/","vi":"tọa độ","ex":"Find the coordinates of the points where the line intersects the parabola."},{"t":"independent variable","pos":"noun phrase","ipa":"/ˌɪn.dɪˈpen.dənt ˈveə.ri.ə.bəl/","vi":"biến độc lập","ex":"In the function y = ax², x is the independent variable and y is the dependent variable."}],"dlg":[{"who":"Ms. Alice","text":"Class, the bridge cable has the shape y = ax². If a tower is 75 m high and sits 200 m from the center O, how do we find a?"},{"who":"Student","text":"The top of the tower has coordinates (200; 75), so we write: 75 = a · 200²!"},{"who":"Ms. Alice","text":"Excellent! Our quadratic function is y = 3 over 1600 times x². How do we find the cable height CH at a point H that is 100 m from O?"},{"who":"Student","text":"We substitute x = 100 into the function to calculate the height!"},{"who":"Ms. Alice","text":"Brilliant! y = 3 over 1600 times 100² equals 18.75 meters. What does this value mean?"},{"who":"Student","text":"The height of the cable CH at that point is exactly 18.75 meters!"}],"extras":[]},{"n":19,"en":"QUADRATIC EQUATIONS IN ONE VARIABLE","vi":"PHƯƠNG TRÌNH BẬC HAI MỘT ẨN","page":19,"focus":"","cards":[{"t":"quadratic equation in one variable","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ɪˈkweɪ.ʒən ɪn wʌn ˈveə.ri.ə.bəl/","vi":"phương trình bậc hai một ẩn","ex":"A quadratic equation in one variable is a second-degree equation of the form ax² + bx + c = 0 (a ≠ 0)."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"In the equation 2x² − 3x + 1 = 0, the coefficient of x² is 2, and of x is −3."},{"t":"discriminant","pos":"noun","ipa":"/dɪˈskrɪm.ɪ.nənt/","vi":"biệt thức (Delta − Δ)","ex":"We compute the discriminant Δ = b² − 4ac to determine the number of real roots."},{"t":"quadratic formula","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ˈfɔː.mjə.lə/","vi":"công thức nghiệm","ex":"We use the quadratic formula to calculate the exact solutions of any second-degree equation."},{"t":"distinct real solutions","pos":"noun phrase","ipa":"/dɪˈstɪŋkt rɪəl səˈluː.ʃənz/","vi":"hai nghiệm phân biệt","ex":"If the discriminant is positive (Δ > 0), the quadratic equation has two distinct real solutions."},{"t":"repeated root","pos":"noun phrase","ipa":"/rɪˈpiː.tɪd ruːt/","vi":"nghiệm kép","ex":"When the discriminant equals zero (Δ = 0), the equation has a repeated root: x₁ = x₂ = −b / 2a."},{"t":"no real solution","pos":"phrase","ipa":"/nəʊ rɪəl səˈluː.ʃən/","vi":"vô nghiệm (trên tập số thực)","ex":"If Δ < 0, the equation has no real solution because we cannot extract the square root of a negative number."},{"t":"constant term","pos":"noun phrase","ipa":"/ˈkɒn.stənt tɜːm/","vi":"hạng tử tự do / hệ số tự do","ex":"In the equation −5x² + 2x − 7 = 0, the constant term is −7."},{"t":"quadratic term","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk tɜːm/","vi":"hạng tử bậc hai","ex":"The term ax² is the quadratic term, which must always be present in a quadratic equation."},{"t":"linear term","pos":"noun phrase","ipa":"/ˈlɪn.i.ə tɜːm/","vi":"hạng tử bậc nhất","ex":"In ax² + bx + c = 0, bx is the linear term, which can be zero in incomplete quadratic equations."},{"t":"complete the square","pos":"verb phrase","ipa":"/kəmˈpliːt ðə skweə/","vi":"phương pháp biến đổi thành bình phương (trên tập số thực)","ex":"To solve x² − 4x = 1, we add 4 to both sides to complete the square: (x − 2)² = 5."},{"t":"factor","pos":"noun","ipa":"/ˈfæk.tə/","vi":"nhân tử / thừa số","ex":"We can solve the quadratic equation 2x(x − 2) = 0 by setting each factor equal to zero."},{"t":"incomplete quadratic equation","pos":"noun phrase","ipa":"/ˌɪn.kəmˈpliːt kwɒˈdræt.ɪk ɪˈkweɪ.ʒən/","vi":"phương trình bậc hai khuyết","ex":"The equation 2x² − 4x = 0 is an incomplete quadratic equation because its constant term is zero."},{"t":"solve","pos":"verb","ipa":"/sɒlv/","vi":"giải (phương trình)","ex":"We apply factoring, completing the square, or the formula to solve the quadratic equation."},{"t":"approximate solution","pos":"noun phrase","ipa":"/əˈprɒk.sɪ.mət səˈluː.ʃən/","vi":"nghiệm gần đúng","ex":"Use a calculator to find the approximate solution of the equation, rounded to two decimal places."}],"dlg":[{"who":"Ms. Alice","text":"Class, we have a land of 28 meters by 16 meters. How do we write the area of the inner swimming pool of 288 square meters with a path of width x?"},{"who":"Student","text":"The pool's length is 28 − 2x and its width is 16 − 2x, so the area is (28 − 2x)(16 − 2x) = 288!"},{"who":"Ms. Alice","text":"Perfect! Expanding and simplifying gives us the quadratic equation: x² − 22x + 40 = 0. Let's solve it!"},{"who":"Student","text":"Using factoring, we write it as (x − 2)(x − 20) = 0. We get x = 2 or x = 20!"},{"who":"Ms. Alice","text":"Excellent! Since the path width x must be less than half of the land's width, which solution do we keep?"},{"who":"Student","text":"We must reject x = 20. The path's width is exactly 2 meters! It satisfies our condition perfectly!"}],"extras":[{"title":"Tip","text":"Master these terms and solve problems involving quadratic equations to apply mathematics in real-life situations."}]},{"n":20,"en":"VIÈTE'S THEOREM AND APPLICATIONS","vi":"ĐỊNH LÍ VIÈTE VÀ ỨNG DỤNG","page":20,"focus":"","cards":[{"t":"Viète's theorem","pos":"noun phrase","ipa":"/viːˈets ˈθɪə.rəm/","vi":"định lí Viète","ex":"By Viète's theorem, the sum of the roots of the equation x² − 5x + 6 = 0 is 5."},{"t":"quadratic equation","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ɪˈkweɪ.ʒən/","vi":"phương trình bậc hai","ex":"The equation ax² + bx + c = 0 is a quadratic equation when a is not equal to zero."},{"t":"coefficient","pos":"noun","ipa":"/ˌkəʊ.ɪˈfɪʃ.ənt/","vi":"hệ số","ex":"In the equation 2x² + 11x + 7 = 0, the coefficient of the leading term is 2."},{"t":"root","pos":"noun","ipa":"/ruːt/","vi":"nghiệm (của phương trình)","ex":"The quadratic equation has two roots, denoted as x₁ and x₂."},{"t":"sum of roots","pos":"noun phrase","ipa":"/sʌm əv ruːts/","vi":"tổng hai nghiệm","ex":"The sum of roots is calculated using the formula x₁ + x₂ = −b / a."},{"t":"product of roots","pos":"noun phrase","ipa":"/ˈprɒd.ʌkt əv ruːts/","vi":"tích hai nghiệm","ex":"The product of roots is given by the expression x₁ · x₂ = c / a."},{"t":"discriminant","pos":"noun","ipa":"/dɪˈskrɪm.ɪ.nənt/","vi":"biệt thức (đenta)","ex":"We calculate the discriminant Δ = b² − 4ac to check if the equation has real roots."},{"t":"distinct roots","pos":"noun phrase","ipa":"/dɪˈstɪŋkt ruːts/","vi":"nghiệm phân biệt","ex":"If the discriminant is positive, the quadratic equation has two distinct roots."},{"t":"repeated root","pos":"noun phrase","ipa":"/rɪˈpiː.tɪd ruːt/","vi":"nghiệm kép","ex":"When Δ = 0, the equation has a repeated root x₁ = x₂ = −b / 2a."},{"t":"no solution","pos":"noun phrase","ipa":"/nəʊ səˈluː.ʃən/","vi":"vô nghiệm","ex":"Because the discriminant is negative, this equation has no solution in real numbers."},{"t":"mental calculation","pos":"noun phrase","ipa":"/ˈmen.təl ˌkæl.kjəˈleɪ.ʃən/","vi":"tính nhẩm / nhẩm nghiệm","ex":"Use mental calculation to solve the equation 2x² − 9x + 7 = 0 since the coefficients sum up to zero."},{"t":"sum","pos":"noun","ipa":"/sʌm/","vi":"tổng (ký hiệu S)","ex":"If two numbers have a sum S and product P, they are roots of x² − Sx + P = 0."},{"t":"product","pos":"noun","ipa":"/ˈprɒd.ʌkt/","vi":"tích (ký hiệu P)","ex":"The product of the two unknown numbers is equal to 96."},{"t":"factorization","pos":"noun","ipa":"/ˌfæk.tər.aɪˈzeɪ.ʃən/","vi":"phân tích thành nhân tử","ex":"By finding the roots, we can complete the factorization: ax² + bx + c = a(x − x₁)(x − x₂)."},{"t":"dimension","pos":"noun","ipa":"/daɪˈmen.ʃən/","vi":"kích thước","ex":"We need to find the dimensions of the rectangular garden with an area of 96 square meters."}],"dlg":[{"who":"Ms. Alice","text":"Class, Bác An has 40 m of fencing to enclose a rectangular garden of 96 m². How do we find its dimensions?"},{"who":"Student","text":"Since the perimeter is 2(width + length) = 40, the sum of the dimensions is S = 20 meters!"},{"who":"Ms. Alice","text":"Perfect! We have their sum S = 20 and product P = 96. What is our corresponding quadratic equation?"},{"who":"Student","text":"We can set up the equation: x² − 20x + 96 = 0!"},{"who":"Ms. Alice","text":"Excellent! Solving this gives us x = 12 or x = 8. Do both values satisfy our conditions?"},{"who":"Student","text":"Yes! Both are positive, so the dimensions of the garden are exactly 12 meters and 8 meters!"}],"extras":[{"title":"Viète's theorem","text":"For ax² + bx + c = 0 with a not equal to 0: the sum of roots is minus b over a, and the product of roots is c over a."},{"title":"Discriminant","text":"If delta is greater than 0, two distinct roots. If delta equals 0, one repeated root. If delta is less than 0, no real root."},{"title":"From sum S and product P","text":"If two numbers have sum S and product P, they are roots of x² − Sx + P = 0."}]},{"n":21,"en":"SOLVING WORD PROBLEMS BY SETTING UP A QUADRATIC EQUATION","vi":"GIẢI BÀI TOÁN BẰNG CÁCH LẬP PHƯƠNG TRÌNH BẬC HAI","page":21,"focus":"","cards":[{"t":"word problem","pos":"noun phrase","ipa":"/ˈwɜːd ˌprɒb.ləm/","vi":"bài toán có lời văn / bài toán thực tế","ex":"We can model this financial situation as a math word problem."},{"t":"set up an equation","pos":"verb phrase","ipa":"/set ʌp ən ɪˈkweɪ.ʒən/","vi":"lập phương trình","ex":"The first step to solve the problem is to set up an equation in terms of x."},{"t":"quadratic equation","pos":"noun phrase","ipa":"/kwɒˈdræt.ɪk ɪˈkweɪ.ʒən/","vi":"phương trình bậc hai","ex":"The word problem leads to a quadratic equation: x² + 30x − 1800 = 0."},{"t":"variable","pos":"noun","ipa":"/ˈveə.ri.ə.bəl/","vi":"ẩn số / biến số","ex":"Let the variable x represent the interest rate as a decimal."},{"t":"condition","pos":"noun","ipa":"/kənˈdɪʃ.ən/","vi":"điều kiện (của ẩn)","ex":"Since the speed must be positive, we set the condition x > 3."},{"t":"express","pos":"verb","ipa":"/ɪkˈspres/","vi":"biểu thị / biểu diễn","ex":"Express the travel time of the boat downstream in terms of x."},{"t":"compound interest","pos":"noun phrase","ipa":"/ˈkɒm.paʊnd ˈɪn.trəst/","vi":"lãi kép","ex":"Bác Lan deposited 100 million VND into the bank under compound interest."},{"t":"interest rate","pos":"noun phrase","ipa":"/ˈɪn.trəst reɪt/","vi":"lãi suất","ex":"We need to calculate the annual interest rate of this savings account."},{"t":"principal","pos":"noun","ipa":"/ˈprɪn.sə.pəl/","vi":"tiền vốn / tiền gửi ban đầu","ex":"The principal of 100 million VND grows to 118.81 million VND after two years."},{"t":"actual speed","pos":"noun phrase","ipa":"/ˈæk.tʃu.əl spiːd/","vi":"vận tốc thực (khi nước yên lặng)","ex":"Let x be the actual speed of the tourist boat in still water."},{"t":"downstream","pos":"adverb / adjective","ipa":"/ˌdaʊnˈstriːm/","vi":"xuôi dòng","ex":"The speed of the boat downstream is the actual speed plus the current speed."},{"t":"upstream","pos":"adverb / adjective","ipa":"/ˌʌpˈstriːm/","vi":"ngược dòng","ex":"Running upstream, the boat's speed is reduced by the current of three kilometers per hour."},{"t":"current speed","pos":"noun phrase","ipa":"/ˈkʌr.ənt spiːd/","vi":"vận tốc dòng nước","ex":"The current speed of the river is three kilometers per hour."},{"t":"satisfy","pos":"verb","ipa":"/ˈsæt.ɪs.faɪ/","vi":"thỏa mãn (điều kiện)","ex":"The positive value x = 15 satisfies our initial condition x > 3."},{"t":"reject","pos":"verb","ipa":"/rɪˈdʒekt/","vi":"loại / không thỏa mãn","ex":"We must reject the negative solution x = −3/5 since speed cannot be negative."}],"dlg":[{"who":"Ms. Alice","text":"Class, a boat makes a round trip of 36 km each way. Total time is 5.5 hours, including a 30-minute rest at B. How do we write the travel equation?"},{"who":"Student","text":"The total traveling time is 5 hours. Let x be the actual speed of the boat, where x must satisfy the condition x > 3."},{"who":"Ms. Alice","text":"Perfect! Now express the times in terms of x and set up the equation."},{"who":"Student","text":"The time downstream is 36 over x + 3, and upstream is 36 over x − 3. So our equation is: 36 over x + 3 plus 36 over x − 3 equals 5!"},{"who":"Ms. Alice","text":"Excellent! Solving this quadratic equation gives us x = 15 or x = −0.6. Which value do we keep?"},{"who":"Student","text":"We must reject x = −0.6 because speed cannot be negative. The actual speed is exactly 15 km/h!"}],"extras":[]},{"n":22,"en":"FREQUENCY TABLES AND FREQUENCY DIAGRAMS","vi":"BẢNG TẦN SỐ VÀ BIỂU ĐỒ TẦN SỐ","page":22,"focus":"","cards":[{"t":"statistics","pos":"noun","ipa":"/stəˈtɪs.tɪks/","vi":"thống kê / khoa học thống kê","ex":"Statistics is the science of collecting, analyzing, and presenting data."},{"t":"data","pos":"noun, plural","ipa":"/ˈdeɪ.tə/","vi":"dữ liệu","ex":"We collect the sizes of shoes worn by male students in the class as our raw data."},{"t":"sample","pos":"noun","ipa":"/ˈsɑːm.pəl/","vi":"mẫu dữ liệu","ex":"The collected data from 30 students represents a sample of the entire school population."},{"t":"sample size","pos":"noun phrase","ipa":"/ˈsɑː.mpəl saɪz/","vi":"cỡ mẫu","ex":"The sample size is denoted by n, representing the total number of observations."},{"t":"frequency","pos":"noun","ipa":"/ˈfriː.kwən.si/","vi":"tần số","ex":"The frequency of shoe size 38 in our dataset is eight, meaning eight boys wear this size."},{"t":"frequency table","pos":"noun phrase","ipa":"/ˈfriː.kwən.si ˈteɪ.bəl/","vi":"bảng tần số","ex":"A frequency table lists each distinct value alongside its corresponding frequency."},{"t":"value","pos":"noun","ipa":"/ˈvæl.juː/","vi":"giá trị","ex":"In this survey, shoe sizes like 36, 37, and 38 are distinct values of the variable."},{"t":"frequency diagram","pos":"noun phrase","ipa":"/ˈfriː.kwən.si ˈdaɪ.ə.ɡræm/","vi":"biểu đồ tần số","ex":"We can represent a frequency table visually by constructing a frequency diagram."},{"t":"horizontal axis","pos":"noun phrase","ipa":"/ˌhɒr.ɪˈzɒn.təl ˈæk.sɪs/","vi":"trục ngang","ex":"We represent the distinct data values along the horizontal axis."},{"t":"vertical axis","pos":"noun phrase","ipa":"/ˈvɜː.tɪ.kəl ˈæk.sɪs/","vi":"trục đứng","ex":"The vertical axis is calibrated to show the frequencies of the collected data."},{"t":"bar chart","pos":"noun phrase","ipa":"/bɑː tʃɑːt/","vi":"biểu đồ dạng cột","ex":"Draw a bar chart where the height of each column corresponds to the frequency of that category."},{"t":"line graph","pos":"noun phrase","ipa":"/laɪn ɡrɑːf/","vi":"biểu đồ dạng đoạn thẳng","ex":"In a line graph, points representing value and frequency are plotted and connected by line segments."},{"t":"frequency polygon","pos":"noun phrase","ipa":"/ˈfriː.kwən.si ˈpɒl.ɪ.ɡən/","vi":"đa giác tần số","ex":"A frequency polygon is a line graph used to visualize the shape of a frequency distribution."},{"t":"pictogram","pos":"noun","ipa":"/ˈpɪk.tə.ɡræm/","vi":"biểu đồ tranh","ex":"In a pictogram, symbols or icons are used to represent frequencies of different groups."},{"t":"represent","pos":"verb","ipa":"/ˌrep.rɪˈzent/","vi":"biểu diễn / thể hiện","ex":"We can represent the distribution of data points using a column frequency chart."}],"dlg":[{"who":"Ms. Alice","text":"Class, Huy collected the shoe sizes of 22 boys. How can we organize this raw data sample?"},{"who":"Student","text":"We can count the frequency of each shoe size and construct a frequency table!"},{"who":"Ms. Alice","text":"Wonderful! Looking at our frequency table, which size has the highest frequency?"},{"who":"Student","text":"Size 38 has the highest frequency of 8. It's the most common shoe size among the boys!"},{"who":"Ms. Alice","text":"Perfect! Now we represent this table visually on coordinate axes. What chart should we use?"},{"who":"Student","text":"We draw a bar chart! The height of each column on the vertical axis represents its frequency!"}],"extras":[]},{"n":23,"en":"RELATIVE FREQUENCY TABLES AND RELATIVE FREQUENCY DIAGRAMS","vi":"BẢNG TẦN SỐ TƯƠNG ĐỐI VÀ BIỂU ĐỒ TẦN SỐ TƯƠNG ĐỐI","page":23,"focus":"","cards":[{"t":"relative frequency","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv ˈfriː.kwən.si/","vi":"tần số tương đối / tần suất","ex":"The relative frequency of a value is the ratio of its frequency to the total sample size."},{"t":"relative frequency table","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv ˈfriː.kwən.si ˈteɪ.bəl/","vi":"bảng tần số tương đối","ex":"A relative frequency table shows the percentage of times each value occurs in the dataset."},{"t":"percentage","pos":"noun","ipa":"/pəˈsen.tɪdʒ/","vi":"tỉ lệ phần trăm","ex":"The relative frequency is often expressed as a percentage, such as forty percent."},{"t":"pie chart","pos":"noun phrase","ipa":"/paɪ tʃɑːt/","vi":"biểu đồ hình quạt tròn","ex":"We can use a pie chart to visualize the distribution of relative frequencies."},{"t":"circular sector","pos":"noun phrase","ipa":"/ˈsɜː.kjə.lə ˈsek.tə/","vi":"hình quạt tròn","ex":"Each circular sector in a pie chart represents a specific data category."},{"t":"central angle","pos":"noun phrase","ipa":"/ˈsen.trəl ˈæŋ.ɡəl/","vi":"góc ở tâm","ex":"To draw a sector representing fifty percent, we calculate its central angle to be one hundred eighty degrees."},{"t":"arc measure","pos":"noun phrase","ipa":"/ɑːk ˈmeʒ.ə/","vi":"số đo cung","ex":"The central angle of a circular sector is equal in measure to its corresponding arc measure."},{"t":"sum of relative frequencies","pos":"noun phrase","ipa":"/sʌm əv ˈrel.ə.tɪv ˈfriː.kwən.siz/","vi":"tổng các tần số tương đối (luôn bằng 100%)","ex":"The sum of relative frequencies in any sample must always equal one hundred percent."},{"t":"horizontal axis","pos":"noun phrase","ipa":"/ˌhɒr.ɪˈzɒn.təl ˈæk.sɪs/","vi":"trục ngang","ex":"On a relative frequency bar chart, different data values are listed along the horizontal axis."},{"t":"vertical axis","pos":"noun phrase","ipa":"/ˈvɜː.tɪ.kəl ˈæk.sɪs/","vi":"trục đứng","ex":"The vertical axis represents the relative frequency calibrated from zero to one hundred percent."},{"t":"relative frequency bar chart","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv ˈfriː.kwən.si bɑː tʃɑːt/","vi":"biểu đồ tần số tương đối dạng cột","ex":"We represent the daily air quality index using a relative frequency bar chart."},{"t":"relative frequency line graph","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv ˈfriː.kwən.si laɪn ɡrɑːf/","vi":"biểu đồ tần số tương đối dạng đoạn thẳng","ex":"A relative frequency line graph is useful to show changes or trends across categories."},{"t":"estimate","pos":"noun / verb","ipa":"/ˈes.tɪ.meɪt/","vi":"ước lượng","ex":"The relative frequency can be used to estimate the probability of a future event."},{"t":"probability","pos":"noun","ipa":"/ˌprɒb.əˈbɪl.ə.ti/","vi":"xác suất","ex":"We can estimate the probability of getting a red ball from the bag based on our 30 trials."},{"t":"sample size","pos":"noun phrase","ipa":"/ˈsɑː.mpəl saɪz/","vi":"cỡ mẫu","ex":"In a statistics experiment, the sample size is denoted by the letter n."}],"dlg":[{"who":"Ms. Alice","text":"Class, our sample size is 40. How do we find the relative frequency of the Comedy genre?"},{"who":"Student","text":"We divide its frequency 20 by the sample size 40, which gives us 0.5, or exactly 50%!"},{"who":"Ms. Alice","text":"Excellent! Now, how can we represent this dataset using a pie chart?"},{"who":"Student","text":"We must calculate the central angle for each circular sector by multiplying its relative frequency by 360 degrees!"},{"who":"Ms. Alice","text":"Brilliant! So our angles are 180 degrees for Comedy, 135 degrees for Sci-Fi, and 45 degrees for Horror. What is the sum of these relative frequencies?"},{"who":"Student","text":"The sum is 50% + 37.5% + 12.5% = 100%! Our pie chart is perfectly complete!"}],"extras":[{"title":"Tip","text":"Master these terms to collect, organize, and analyze data using relative frequencies and visual representations."}]},{"n":24,"en":"GROUPED FREQUENCY TABLES AND DIAGRAMS","vi":"BẢNG TẦN SỐ GHÉP NHÓM VÀ BIỂU ĐỒ","page":24,"focus":"","cards":[{"t":"grouped data","pos":"noun phrase","ipa":"/ɡruːpt ˈdeɪ.tə/","vi":"dữ liệu ghép nhóm / số liệu ghép nhóm","ex":"We organize the raw heights of forty students into grouped data to make it easier to analyze."},{"t":"grouped frequency table","pos":"noun phrase","ipa":"/ɡruːpt ˈfriː.kwən.si ˈteɪ.bəl/","vi":"bảng tần số ghép nhóm","ex":"The teacher constructed a grouped frequency table to show the distribution of student test scores."},{"t":"grouped relative frequency table","pos":"noun phrase","ipa":"/ɡruːpt ˈrel.ə.tɪv ˈfriː.kwən.si ˈteɪ.bəl/","vi":"bảng tần số tương đối ghép nhóm","ex":"Convert the raw counts into a grouped relative frequency table to display the percentages."},{"t":"class interval","pos":"noun phrase","ipa":"/klɑːs ˈɪn.tə.vəl/","vi":"nhóm số liệu / khoảng ghép nhóm","ex":"Each class interval has a width of four centimeters, such as the group from 150 to under 158 cm."},{"t":"left endpoint","pos":"noun phrase","ipa":"/left ˈend.pɔɪnt/","vi":"đầu mút trái / giới hạn dưới","ex":"In the semi-open interval [150; 158), the number 150 is the left endpoint and is included in the group."},{"t":"right endpoint","pos":"noun phrase","ipa":"/raɪt ˈend.pɔɪnt/","vi":"đầu mút phải / giới hạn trên","ex":"The right endpoint is not included in the interval [150; 158), so 158 belongs to the next group."},{"t":"representative value","pos":"noun phrase","ipa":"/ˌrep.rɪˈzen.tə.tɪv ˈvæl.juː/","vi":"giá trị đại diện","ex":"The representative value of the interval [150; 158) is calculated as 154, which is its midpoint."},{"t":"histogram","pos":"noun","ipa":"/ˈhɪs.tə.ɡræm/","vi":"biểu đồ tần số (tần số tương đối) ghép nhóm dạng cột / tổ chức đồ","ex":"We can visualize the continuous distribution of student heights by drawing a histogram."},{"t":"frequency polygon","pos":"noun phrase","ipa":"/ˈfriː.kwən.si ˈpɒl.ɪ.ɡən/","vi":"đa giác tần số / biểu đồ dạng đoạn thẳng ghép nhóm","ex":"A frequency polygon is constructed by connecting the midpoints of the histogram bars."},{"t":"relative frequency","pos":"noun phrase","ipa":"/ˈrel.ə.tɪv ˈfriː.kwən.si/","vi":"tần số tương đối / tỉ lệ phần trăm","ex":"The relative frequency of a group is its frequency divided by the total sample size."},{"t":"frequency","pos":"noun","ipa":"/ˈfriː.kwən.si/","vi":"tần số","ex":"The class interval [158; 161) has a frequency of 12, representing 12 students."},{"t":"sample size","pos":"noun phrase","ipa":"/ˈsɑː.mpəl saɪz/","vi":"cỡ mẫu","ex":"The study of student learning times has a sample size of 40 participants."},{"t":"midpoint","pos":"noun","ipa":"/ˈmɪd.pɔɪnt/","vi":"trung điểm","ex":"Find the representative value of an interval by calculating its midpoint."},{"t":"continuous data","pos":"noun phrase","ipa":"/kənˈtɪn.ju.əs ˈdeɪ.tə/","vi":"dữ liệu liên tục","ex":"Measurements such as weight, height, and time are categorized as continuous data."},{"t":"class width","pos":"noun phrase","ipa":"/klɑːs wɪdθ/","vi":"độ dài nhóm / khoảng cách nhóm","ex":"To find the class width, we subtract the left endpoint from the right endpoint."}],"dlg":[{"who":"Ms. Alice","text":"Class, we measured the heights of forty students. Since there are too many unique values, how should we organize this raw data?"},{"who":"Student","text":"We should group them into class intervals of equal width to construct a grouped frequency table!"},{"who":"Ms. Alice","text":"Excellent! We get a frequency of 5 for the interval [150; 158). How can we calculate its relative frequency?"},{"who":"Student","text":"We divide the frequency by the sample size of 40! So the relative frequency is 5 over 40, which is 12.5%!"},{"who":"Ms. Alice","text":"Perfect! Now we represent this grouped relative frequency table visually. What diagram should we draw?"},{"who":"Student","text":"We draw a histogram! Its adjacent columns represent each interval, and their heights show the relative frequencies!"}],"extras":[{"title":"Key formulas","text":"Relative frequency equals frequency divided by total sample size. Percentage equals relative frequency times 100 percent. Class interval [a; b) includes a but not b. Representative value equals a plus b over 2."}]},{"n":25,"en":"RANDOM EXPERIMENTS AND SAMPLE SPACES","vi":"PHÉP THỬ NGẪU NHIÊN VÀ KHÔNG GIAN MẪU","page":25,"focus":"","cards":[{"t":"random experiment","pos":"noun phrase","ipa":"/ˈræn.dəm ɪkˈsper.ɪ.mənt/","vi":"phép thử ngẫu nhiên","ex":"Tossing a coin or rolling a die is a classic example of a random experiment."},{"t":"sample space","pos":"noun phrase","ipa":"/ˈsɑːm.pəl speɪs/","vi":"không gian mẫu","ex":"The sample space of rolling a standard six-sided die is represented as Ω = {1, 2, 3, 4, 5, 6}."},{"t":"outcome","pos":"noun","ipa":"/ˈaʊt.kʌm/","vi":"kết quả có thể xảy ra","ex":"Each possible outcome of the coin toss is represented by either Heads or Tails."},{"t":"coin","pos":"noun","ipa":"/kɔɪn/","vi":"đồng xu","ex":"We toss a fair coin to observe which face lands face up."},{"t":"die","pos":"noun","ipa":"/daɪ/","vi":"con xúc xắc","ex":"A standard fair die has six faces numbered from one to six."},{"t":"heads","pos":"noun, plural","ipa":"/hedz/","vi":"mặt sấp (ký hiệu S)","ex":"Let S represent the heads outcome when tossing the coin."},{"t":"tails","pos":"noun, plural","ipa":"/teɪlz/","vi":"mặt ngửa (ký hiệu N)","ex":"The coin lands on tails, which we denote as N."},{"t":"toss","pos":"verb / noun","ipa":"/tɒs/","vi":"tung / gieo (đồng xu)","ex":"We toss a coin and roll a die simultaneously in this probability experiment."},{"t":"roll","pos":"verb","ipa":"/rəʊl/","vi":"gieo / lăn (xúc xắc)","ex":"When you roll the die, there are six equally likely outcomes."},{"t":"element","pos":"noun","ipa":"/ˈel.ɪ.mənt/","vi":"phần tử","ex":"Each individual pair in the sample space is called an element."},{"t":"spin","pos":"verb / noun","ipa":"/spɪn/","vi":"quay / vòng quay","ex":"Spin the circular board twice to observe the numbers indicated by the pointer."},{"t":"pointer","pos":"noun","ipa":"/ˈpɔɪn.tə/","vi":"kim chỉ / mũi tên","ex":"Observe which numbered sector the pointer indicates when the wheel stops."},{"t":"set","pos":"noun","ipa":"/set/","vi":"tập hợp","ex":"The sample space is a set containing all possible outcomes of the trial."},{"t":"list","pos":"verb","ipa":"/lɪst/","vi":"liệt kê","ex":"We can list all the elements of the sample space in a neat two-dimensional table."},{"t":"genotype","pos":"noun","ipa":"/ˈdʒen.ə.taɪp/","vi":"kiểu gen","ex":"In a biological experiment, the genotype of the offspring represents a random outcome."}],"dlg":[{"who":"Ms. Alice","text":"Class! We draw two slips from this box one by one without replacing the first slip. What is this experiment?"},{"who":"Student","text":"It is a random experiment because we cannot predict the exact names drawn beforehand!"},{"who":"Ms. Alice","text":"Correct! Since the first slip is not returned, can we draw the same name twice?"},{"who":"Student","text":"No, Ms. Alice! The first draw A cannot equal the second draw B. So pairs like (A, A) are impossible!"},{"who":"Ms. Alice","text":"Wonderful! Let's list the sample space. How many elements does it contain?"},{"who":"Student","text":"We have pairs from (A, B) to (D, C). The sample space Ω has exactly twelve possible outcomes!"}],"extras":[]},{"n":26,"en":"PROBABILITY OF AN EVENT RELATED TO A TRIAL","vi":"XÁC SUẤT CỦA BIẾN CỐ LIÊN QUAN TỚI PHÉP THỬ","page":26,"focus":"","cards":[{"t":"random trial","pos":"noun phrase","ipa":"/ˈræn.dəm ˈtraɪ.əl/","vi":"phép thử ngẫu nhiên","ex":"A random trial is an action whose outcome cannot be predicted with certainty."},{"t":"sample space","pos":"noun phrase","ipa":"/ˈsɑːm.pəl speɪs/","vi":"không gian mẫu","ex":"The sample space of a trial is the set of all possible outcomes, denoted by the Greek letter Ω."},{"t":"event","pos":"noun","ipa":"/ɪˈvent/","vi":"biến cố","ex":"An event is a subset of the sample space whose occurrence depends on the trial's outcome."},{"t":"favorable outcome","pos":"noun phrase","ipa":"/ˈfeɪ.vər.ə.bəl ˈaʊt.kʌm/","vi":"kết quả thuận lợi","ex":"An outcome is a favorable outcome for event E if it makes E occur."},{"t":"equally likely","pos":"adjective phrase","ipa":"/ˈiː.kwə.li ˈlaɪk.li/","vi":"đồng khả năng","ex":"Since the coin is fair, the outcomes heads and tails are equally likely."},{"t":"probability","pos":"noun","ipa":"/ˌprɒb.əˈbɪl.ə.ti/","vi":"xác suất","ex":"The probability of an event E is calculated by dividing the number of favorable outcomes by the total number of possible outcomes."},{"t":"ratio","pos":"noun","ipa":"/ˈreɪ.ʃi.əʊ/","vi":"tỉ số","ex":"Find the ratio of the number of elements of set E to the number of elements of the sample space."},{"t":"element","pos":"noun","ipa":"/ˈel.ɪ.mənt/","vi":"phần tử","ex":"The sample space Ω has twelve elements in this coin-and-die rolling experiment."},{"t":"set","pos":"noun","ipa":"/set/","vi":"tập hợp","ex":"The sample space is the set of all possible outcomes of a random trial."},{"t":"describe","pos":"verb","ipa":"/dɪˈskraɪb/","vi":"mô tả (bằng cách liệt kê)","ex":"Describe the favorable outcomes for the event where the sum of two rolls is prime."},{"t":"experiment","pos":"noun","ipa":"/ɪkˈsper.ɪ.mənt/","vi":"thực nghiệm / thí nghiệm","ex":"We can perform a probability experiment by rolling a six-sided die thirty times."},{"t":"determine","pos":"verb","ipa":"/dɪˈtɜː.mɪn/","vi":"xác định / tính toán","ex":"We need to determine the probability that the student selects a green card."},{"t":"impossible event","pos":"noun phrase","ipa":"/ɪmˈpɒs.ə.bəl ɪˈvent/","vi":"biến cố không thể","ex":"An impossible event has a probability of zero because it can never occur."},{"t":"sure event","pos":"noun phrase","ipa":"/ʃɔː ɪˈvent/","vi":"biến cố chắc chắn","ex":"A sure event has a probability of one because it is certain to happen."},{"t":"denote","pos":"verb","ipa":"/dɪˈnəʊt/","vi":"ký hiệu","ex":"We denote the sample space of our random trial with the Greek letter Ω."}],"dlg":[{"who":"Ms. Alice","text":"Class, a committee has 3 boys and 2 girls. We choose one boy and one girl. How many outcomes does the sample space have?"},{"who":"Student","text":"We can count the pairs: each boy can be paired with each girl, so n(Ω) = 3 times 2 = 6 pairs!"},{"who":"Ms. Alice","text":"Excellent! Now, let's look at event E. How many favorable outcomes exist for choosing a boy and a girl?"},{"who":"Student","text":"Each boy can be paired with each girl, so we have 3 times 2, which gives us 6 favorable outcomes!"},{"who":"Ms. Alice","text":"Perfect calculation! Now, what is the final probability of event E?"},{"who":"Student","text":"P(E) is 6 over 10, which equals 3/5, or exactly sixty percent. The math is beautiful!"}],"extras":[]},{"n":27,"en":"INSCRIBED ANGLES","vi":"GÓC NỘI TIẾP","page":27,"focus":"","cards":[{"t":"inscribed angle","pos":"noun phrase","ipa":"/ɪnˈskraɪbd ˈæŋ.ɡəl/","vi":"góc nội tiếp","ex":"An inscribed angle is an angle whose vertex lies on the circle and whose sides contain chords of the circle."},{"t":"intercepted arc","pos":"noun phrase","ipa":"/ˌɪn.təˈsep.tɪd ɑːk/","vi":"cung bị chắn","ex":"The arc that lies in the interior of an inscribed angle is called the intercepted arc."},{"t":"vertex","pos":"noun","ipa":"/ˈvɜː.teks/","vi":"đỉnh (của góc)","ex":"For the inscribed angle ACB, the vertex C must lie directly on the circumference of the circle."},{"t":"chord","pos":"noun","ipa":"/kɔːd/","vi":"dây cung / dây","ex":"The two sides of an inscribed angle contain chords of the circle, such as CA and CB."},{"t":"central angle","pos":"noun phrase","ipa":"/ˈsen.trəl ˈæŋ.ɡəl/","vi":"góc ở tâm","ex":"The measure of an inscribed angle is equal to half the measure of the central angle that intercepts the same arc."},{"t":"measure of an arc","pos":"noun phrase","ipa":"/ˈmeʒ.ə əv ən ɑːk/","vi":"số đo cung","ex":"The measure of an inscribed angle is always half the measure of its intercepted arc."},{"t":"semicircle","pos":"noun","ipa":"/ˈsem.iˌsɜː.kəl/","vi":"nửa đường tròn","ex":"An inscribed angle that intercepts a semicircle is always a right angle."},{"t":"right angle","pos":"noun phrase","ipa":"/raɪt ˈæŋ.ɡəl/","vi":"góc vuông","ex":"The inscribed angle AMB is a right angle because its intercepted arc is a semicircle."},{"t":"subtend","pos":"verb","ipa":"/səbˈtend/","vi":"chắn / nhận chắn (cung)","ex":"Inscribed angles that subtend the same arc are equal in measure."},{"t":"congruent arcs","pos":"noun phrase","ipa":"/ˈkɒŋ.ɡru.ənt ɑːks/","vi":"các cung bằng nhau","ex":"Inscribed angles that intercept congruent arcs are equal in measure."},{"t":"intersect","pos":"verb","ipa":"/ˌɪn.təˈsekt/","vi":"cắt nhau / giao nhau","ex":"Two chords AB and CD intersect at a point X inside the circle."},{"t":"collinear","pos":"adjective","ipa":"/kəʊˈlɪn.i.ə/","vi":"thẳng hàng","ex":"In Case 1 of the proof, the center O, the vertex C, and point B are collinear."},{"t":"theorem","pos":"noun","ipa":"/ˈθɪə.rəm/","vi":"định lí","ex":"According to the inscribed angle theorem, the measure of angle ACB is half of the intercepted arc AB."},{"t":"prove","pos":"verb","ipa":"/pruːv/","vi":"chứng minh","ex":"We can prove the theorem by considering three distinct cases depending on the location of the center O."},{"t":"inscribed triangle","pos":"noun phrase","ipa":"/ɪnˈskraɪbd ˈtraɪ.æŋ.ɡəl/","vi":"tam giác nội tiếp","ex":"An inscribed triangle is a triangle whose vertices all lie on a circle."}],"dlg":[{"who":"Ms. Alice","text":"Class, look at this soccer field model. The goalposts A and B lie on a circle, and the penalty spot P is also on the circle. What is angle APB?"},{"who":"Student","text":"Since its vertex P lies on the circle and its sides contain chords PA and PB, it is an inscribed angle!"},{"who":"Ms. Alice","text":"Great! If the kick angle from the penalty spot P is 36 degrees, what is the measure of the intercepted arc AB?"},{"who":"Student","text":"By the inscribed angle theorem, the angle is half the arc measure. So the intercepted arc AB must measure 72 degrees!"},{"who":"Ms. Alice","text":"Exactly! Now, if we move the ball to another point Q on the same arc of the circle, what is the new kick angle AQB?"},{"who":"Student","text":"It is also an inscribed angle subtending the same arc AB, so the kick angle remains exactly 36 degrees! That is amazing!"}],"extras":[{"title":"Tip","text":"Master these terms to understand and solve problems involving inscribed angles and circle geometry."}]},{"n":28,"en":"CIRCUMSCRIBED AND INSCRIBED CIRCLES OF A TRIANGLE","vi":"ĐƯỜNG TRÒN NGOẠI TIẾP VÀ ĐƯỜNG TRÒN NỘI TIẾP CỦA MỘT TAM GIÁC","page":28,"focus":"","cards":[{"t":"circumscribed circle","pos":"noun phrase","ipa":"/ˌsɜː.kəmˈskraɪbd ˈsɜː.kəl/","vi":"đường tròn ngoại tiếp (tam giác)","ex":"The circumscribed circle of a triangle passes through all three of its vertices."},{"t":"inscribed circle","pos":"noun phrase","ipa":"/ɪnˈskraɪbd ˈsɜː.kəl/","vi":"đường tròn nội tiếp (tam giác)","ex":"An inscribed circle lies completely inside the triangle and is tangent to all three sides."},{"t":"circumcenter","pos":"noun","ipa":"/ˈsɜː.kəmˌsen.tə/","vi":"tâm đường tròn ngoại tiếp","ex":"The circumcenter is the intersection point of the three perpendicular bisectors of the triangle's sides."},{"t":"incenter","pos":"noun","ipa":"/ˈɪn.sen.tə/","vi":"tâm đường tròn nội tiếp","ex":"The incenter of a triangle is the intersection of the three interior angle bisectors."},{"t":"perpendicular bisector","pos":"noun phrase","ipa":"/ˌpɜː.pənˈdɪk.jə.lə baɪˈsek.tə/","vi":"đường trung trực","ex":"Each perpendicular bisector of a triangle's side passes through its midpoint at a right angle."},{"t":"angle bisector","pos":"noun phrase","ipa":"/ˈæŋ.ɡəl baɪˈsek.tə/","vi":"đường phân giác / tia phân giác","ex":"An angle bisector divides one of the triangle's interior angles into two equal measures."},{"t":"equilateral triangle","pos":"noun phrase","ipa":"/ˌiː.kwɪˈlæt.ər.əl ˈtraɪ.æŋ.ɡəl/","vi":"tam giác đều","ex":"In an equilateral triangle, the circumcenter, incenter, orthocenter, and centroid all coincide at the same point."},{"t":"right-angled triangle","pos":"noun phrase","ipa":"/raɪt ˈæŋ.ɡəld ˈtraɪ.æŋ.ɡəl/","vi":"tam giác vuông","ex":"The circumcenter of a right-angled triangle is the midpoint of its hypotenuse."},{"t":"hypotenuse","pos":"noun","ipa":"/haɪˈpɒt.ə.njuːs/","vi":"cạnh huyền","ex":"The hypotenuse is the longest side of a right triangle, lying opposite the right angle."},{"t":"midpoint","pos":"noun","ipa":"/ˈmɪd.pɔɪnt/","vi":"trung điểm","ex":"The midpoint of the hypotenuse is equidistant from all three vertices of the right triangle."},{"t":"centroid","pos":"noun","ipa":"/ˈsen.trɔɪd/","vi":"trọng tâm","ex":"The centroid of an equilateral triangle divides each median in a two-to-one ratio."},{"t":"orthocenter","pos":"noun","ipa":"/ˈɔː.θəʊˌsen.tə/","vi":"trực tâm","ex":"The orthocenter is the point where the three altitudes of a triangle intersect."},{"t":"tangent","pos":"adjective","ipa":"/ˈtæn.dʒənt/","vi":"tiếp xúc","ex":"The inscribed circle is tangent to the three side lines of the triangle."},{"t":"equidistant","pos":"adjective","ipa":"/ˌiː.kwɪˈdɪs.tənt/","vi":"cách đều","ex":"The incenter of a triangle is equidistant from all three of its sides."},{"t":"escribed circle","pos":"noun phrase","ipa":"/ɪˈskraɪbd ˈsɜː.kəl/","vi":"đường tròn bàng tiếp","ex":"An escribed circle lies outside the triangle, tangent to one side and the extensions of the other two."}],"dlg":[{"who":"Ms. Alice","text":"Class! We need to make an equilateral triangular wooden frame to fit this circular clock of diameter 30 cm. What is the relation here?"},{"who":"Student","text":"The circular clock must be the inscribed circle of our equilateral triangle! Its radius r is half of the diameter, so r = 15 cm!"},{"who":"Ms. Alice","text":"Correct! The radius of the inscribed circle of an equilateral triangle with side a is r = a√3 over 6."},{"who":"Student","text":"We can solve for a! Since r = 15 cm, we have 15 = a√3 over 6, which means a = 90 over √3!"},{"who":"Ms. Alice","text":"Excellent! What is the simplified value of the side length a?"},{"who":"Student","text":"a = 30√3 cm! Since √3 is about 1.732, the side length is approximately 52 cm. Now we can build it!"}],"extras":[{"title":"Special cases","text":"Equilateral triangle: the circumcenter, incenter, centroid and orthocenter coincide. Right-angled triangle: the circumcenter is the midpoint of the hypotenuse. Acute triangle: the circumcenter is inside. Obtuse triangle: the circumcenter is outside."},{"title":"Key formulas","text":"Inradius of an equilateral triangle: r = a√3 over 6. Area of a triangle: S = r · s, where s = (a + b + c) over 2."}]},{"n":29,"en":"INSCRIBED QUADRILATERALS","vi":"TỨ GIÁC NỘI TIẾP","page":29,"focus":"","cards":[{"t":"inscribed quadrilateral","pos":"noun phrase","ipa":"/ɪnˈskraɪbd ˌkwɒd.rɪˈlæt.ər.əl/","vi":"tứ giác nội tiếp","ex":"A quadrilateral is called an inscribed quadrilateral if all its four vertices lie on a circle."},{"t":"circumscribed circle","pos":"noun phrase","ipa":"/ˌsɜː.kəmˈskraɪbd ˈsɜː.kəl/","vi":"đường tròn ngoại tiếp (tứ giác)","ex":"The circumscribed circle of a quadrilateral passes through all four of its vertices."},{"t":"convex quadrilateral","pos":"noun phrase","ipa":"/ˈkɒn.veks ˌkwɒd.rɪˈlæt.ər.əl/","vi":"tứ giác lồi","ex":"We only consider convex quadrilaterals when studying cyclic quadrilateral properties."},{"t":"opposite angles","pos":"noun phrase","ipa":"/ˈɒp.ə.zɪt ˈæŋ.ɡəlz/","vi":"các góc đối / các góc đối diện","ex":"In an inscribed quadrilateral, the sum of the opposite angles is always equal to 180 degrees."},{"t":"supplementary","pos":"adjective","ipa":"/ˌsʌp.lɪˈmen.tər.i/","vi":"bù nhau (có tổng số đo bằng 180°)","ex":"The theorem states that the opposite angles of an inscribed quadrilateral are supplementary."},{"t":"vertex","pos":"noun, plural: vertices","ipa":"/ˈvɜː.teks/","vi":"đỉnh","ex":"A cyclic quadrilateral has exactly four vertices lying on the circumference of a circle."},{"t":"diagonal","pos":"noun","ipa":"/daɪˈæɡ.ən.əl/","vi":"đường chéo","ex":"The diagonals of an inscribed rectangle intersect at the center of its circumscribed circle."},{"t":"concurrent","pos":"adjective","ipa":"/kənˈkʌr.ənt/","vi":"đồng quy","ex":"The perpendicular bisectors of the four sides of a cyclic quadrilateral are concurrent at the center of the circle."},{"t":"perpendicular bisector","pos":"noun phrase","ipa":"/ˌpɜː.pənˈdɪk.jə.lə baɪˈsek.tə/","vi":"đường trung trực","ex":"The center of the circumscribed circle is the point where the perpendicular bisectors of the sides intersect."},{"t":"isosceles trapezoid","pos":"noun phrase","ipa":"/aɪˌsɒs.ə.liːz ˈtræp.ɪ.zɔɪd/","vi":"hình thang cân","ex":"An isosceles trapezoid is always an inscribed quadrilateral because its opposite angles sum to 180 degrees."},{"t":"parallelogram","pos":"noun","ipa":"/ˌpær.əˈlel.ə.ɡræm/","vi":"hình bình hành","ex":"If a parallelogram is inscribed in a circle, it must be a rectangle."},{"t":"rectangle","pos":"noun","ipa":"/ˈrek.tæŋ.ɡəl/","vi":"hình chữ nhật","ex":"Every rectangle can be inscribed in a circle with its center at the intersection of its diagonals."},{"t":"square","pos":"noun","ipa":"/skweə/","vi":"hình vuông","ex":"A square is a regular quadrilateral that is always cyclic."},{"t":"intercepted arc","pos":"noun phrase","ipa":"/ˌɪn.təˈsep.tɪd ɑːk/","vi":"cung bị chắn","ex":"The opposite angles of a cyclic quadrilateral intercept two arcs that combine to form the entire circle."},{"t":"theorem","pos":"noun","ipa":"/ˈθɪə.rəm/","vi":"định lí","ex":"We can prove the inscribed quadrilateral theorem using the properties of inscribed angles."}],"dlg":[{"who":"Ms. Alice","text":"Class, since ABCD is an inscribed quadrilateral, how do we find its opposite angle BCD if angle DAB is 70 degrees?"},{"who":"Student","text":"Since the opposite angles of a cyclic quadrilateral are supplementary, angle BCD is 180 − 70 = 110 degrees!"},{"who":"Ms. Alice","text":"Excellent! Now, if angle ABC is 130 degrees, how can we eventually find the intersection angle BXC?"},{"who":"Student","text":"First, we can find its opposite angle CDA, which is 180 − 130 = 50 degrees!"},{"who":"Ms. Alice","text":"Brilliant! Now look at the large triangle AXD. What is the final measure of angle BXC?"},{"who":"Student","text":"In triangle AXD, the sum of angles is 180 degrees, so angle BXC is 180 − 70 − 50 = 60 degrees. That is amazing!"}],"extras":[]},{"n":30,"en":"REGULAR POLYGONS AND ROTATION TRANSFORMATIONS","vi":"ĐA GIÁC ĐỀU VÀ PHÉP QUAY","page":30,"focus":"","cards":[{"t":"polygon","pos":"noun","ipa":"/ˈpɒl.ɪ.ɡɒn/","vi":"đa giác","ex":"A polygon is a flat geometric shape bounded by a closed path of straight line segments."},{"t":"regular polygon","pos":"noun phrase","ipa":"/ˈreɡ.jə.lə ˈpɒl.ɪ.ɡɒn/","vi":"đa giác đều","ex":"A regular polygon is a convex polygon that has all sides equal and all angles equal."},{"t":"convex polygon","pos":"noun phrase","ipa":"/ˈkɒn.veks ˈpɒl.ɪ.ɡɒn/","vi":"đa giác lồi","ex":"If all interior angles of a polygon are less than 180 degrees, it is classified as a convex polygon."},{"t":"vertex","pos":"noun, plural: vertices","ipa":"/ˈvɜː.teks/","vi":"đỉnh (của đa giác)","ex":"A regular pentagon has exactly five vertices, which all lie on its circumscribed circle."},{"t":"side","pos":"noun","ipa":"/saɪd/","vi":"cạnh (của đa giác)","ex":"To find the perimeter of a regular polygon, multiply the length of one side by the total number of sides."},{"t":"interior angle","pos":"noun phrase","ipa":"/ɪnˈtɪə.ri.ə ˈæŋ.ɡəl/","vi":"góc trong (của đa giác)","ex":"Each interior angle of a regular hexagon measures exactly one hundred twenty degrees."},{"t":"regular pentagon","pos":"noun phrase","ipa":"/ˈreɡ.jə.lə ˈpen.tə.ɡɒn/","vi":"ngũ giác đều","ex":"In a regular pentagon, the central angle subtended by each side at the center measures seventy-two degrees."},{"t":"regular hexagon","pos":"noun phrase","ipa":"/ˈreɡ.jə.lə ˈhek.sə.ɡɒn/","vi":"lục giác đều","ex":"A regular hexagon can be partitioned into six congruent equilateral triangles."},{"t":"regular octagon","pos":"noun phrase","ipa":"/ˈreɡ.jə.lə ˈɒk.tə.ɡɒn/","vi":"bát giác đều","ex":"Many road signs, such as the standard STOP sign, are designed in the shape of a regular octagon."},{"t":"circumscribed circle","pos":"noun phrase","ipa":"/ˌsɜː.kəmˈskraɪbd ˈsɜː.kəl/","vi":"đường tròn ngoại tiếp","ex":"The vertices of any regular polygon lie on a unique circle called the circumscribed circle."},{"t":"center of a regular polygon","pos":"noun phrase","ipa":"/ˈsen.tə əv ə ˈreɡ.jə.lə ˈpɒl.ɪ.ɡɒn/","vi":"tâm của đa giác đều","ex":"The center of a regular polygon is the center of its circumscribed circle."},{"t":"rotation","pos":"noun","ipa":"/rəʊˈteɪ.ʃən/","vi":"phép quay","ex":"A rotation of α degrees around center O maps a starting point A to a destination point B."},{"t":"clockwise rotation","pos":"noun phrase","ipa":"/ˈklɒk.waɪz rəʊˈteɪ.ʃən/","vi":"phép quay thuận chiều (kim đồng hồ)","ex":"A clockwise rotation of ninety degrees around the center maps A to B."},{"t":"counterclockwise rotation","pos":"noun phrase","ipa":"/ˌkaʊn.təˈklɒk.waɪz rəʊˈteɪ.ʃən/","vi":"phép quay ngược chiều (kim đồng hồ)","ex":"A counterclockwise rotation of one hundred twenty degrees maps B back to A."},{"t":"angle of rotation","pos":"noun phrase","ipa":"/ˈæŋ.ɡəl əv rəʊˈteɪ.ʃən/","vi":"góc quay","ex":"The angle of rotation determines how far a shape is rotated around its center."}],"dlg":[{"who":"Ms. Alice","text":"Class, this regular hexagon is inscribed in a circle of radius 2 cm. What is the length of its side AB?"},{"who":"Student","text":"The central angle AOB is 360 degrees over 6, which is 60 degrees. Since OA = OB = 2 cm, triangle OAB is equilateral, so AB is also 2 cm!"},{"who":"Ms. Alice","text":"Excellent! Now, who can calculate the measure of each interior angle of this regular hexagon?"},{"who":"Student","text":"For n = 6, the formula gives: (6 − 2) times 180 degrees over 6, which equals 720 over 6, or 120 degrees!"},{"who":"Ms. Alice","text":"Perfect! Finally, what are the angles of rotation about the center O that map this regular hexagon onto itself?"},{"who":"Student","text":"The rotations of 60, 120, 180, 240, 300, or 360 degrees map the regular hexagon onto itself!"}],"extras":[]},{"n":31,"en":"CYLINDER AND CONE","vi":"HÌNH TRỤ VÀ HÌNH NÓN","page":31,"focus":"","cards":[{"t":"cylinder","pos":"noun","ipa":"/ˈsɪl.ɪn.də/","vi":"hình trụ / hình trụ tròn xoay","ex":"When rotating a rectangle one full turn around one fixed side, we obtain a cylinder."},{"t":"cone","pos":"noun","ipa":"/kəʊn/","vi":"hình nón / hình nón tròn xoay","ex":"A classic party hat or a funnel is shaped like a geometric cone."},{"t":"base","pos":"noun","ipa":"/beɪs/","vi":"đáy (mặt đáy)","ex":"A cylinder has two identical circular bases, while a cone has only one circular base."},{"t":"radius of the base","pos":"noun phrase","ipa":"/ˈreɪ.di.əs əv ðə beɪs/","vi":"bán kính đáy","ex":"The volume of a cylinder depends on its height and the radius of its base."},{"t":"height","pos":"noun","ipa":"/haɪt/","vi":"chiều cao / đường cao","ex":"The height of the cylinder is the distance between its two parallel bases."},{"t":"generating line","pos":"noun phrase","ipa":"/ˈdʒen.ə.reɪ.tɪŋ laɪn/","vi":"đường sinh","ex":"Every generating line of a right circular cylinder is equal in length to its height."},{"t":"vertex","pos":"noun, plural: vertices","ipa":"/ˈvɜː.teks/","vi":"đỉnh (của hình nón)","ex":"The vertex of the cone lies directly above the center of its circular base."},{"t":"lateral area","pos":"noun phrase","ipa":"/ˈlæt.ər.əl ˈeə.ri.ə/","vi":"diện tích xung quanh","ex":"The lateral area of a cone is calculated by multiplying pi, the base radius, and the length of the generating line."},{"t":"total surface area","pos":"noun phrase","ipa":"/ˈtəʊ.təl ˈsɜː.fɪs ˈeə.ri.ə/","vi":"diện tích toàn phần","ex":"To find the total surface area of a cylinder, add the lateral area to the areas of both circular bases."},{"t":"volume","pos":"noun","ipa":"/ˈvɒl.juːm/","vi":"thể tích","ex":"The volume of a cone is exactly one-third of the volume of a cylinder with the same base radius and height."},{"t":"net","pos":"noun","ipa":"/net/","vi":"hình khai triển","ex":"The net of a cylinder consists of a rectangle and two congruent circular disks."},{"t":"revolution solid","pos":"noun phrase","ipa":"/ˌrev.əˈluː.ʃən ˈsɒl.ɪd/","vi":"khối tròn xoay / vật thể tròn xoay","ex":"Cylinders and cones are classic revolution solids studied in high school geometry."},{"t":"right circular cylinder","pos":"noun phrase","ipa":"/raɪt ˈsɜː.kjə.lə ˈsɪl.ɪn.də/","vi":"hình trụ đứng / hình trụ tròn xoay","ex":"In a right circular cylinder, the axis is perpendicular to the bases."},{"t":"right circular cone","pos":"noun phrase","ipa":"/raɪt ˈsɜː.kjə.lə kəʊn/","vi":"hình nón tròn xoay","ex":"A right circular cone is generated by rotating a right-angled triangle around one of its legs."},{"t":"axis of rotation","pos":"noun phrase","ipa":"/ˈæk.sɪs əv rəʊˈteɪ.ʃən/","vi":"trục quay","ex":"The fixed line about which a 2D shape is rotated is called the axis of rotation."}],"dlg":[{"who":"Ms. Alice","text":"Class, look at this condensed milk can. It is a cylinder with a radius of 5 cm and a height of 10 cm. How do we find its volume?"},{"who":"Student","text":"We use the volume formula: V = πR²h! That is V = 3.14 times 5 squared times 10, approximately 785 cubic centimeters!"},{"who":"Ms. Alice","text":"Excellent! Now, if we have a cone-shaped funnel with the same radius and height, what is its volume?"},{"who":"Student","text":"A cone's volume is exactly one-third of a cylinder's volume! So, V = one third πR²h, approximately 261.67 cubic centimeters!"},{"who":"Ms. Alice","text":"Brilliant! Let's test this relationship with water. If we pour water from this cone funnel into the can, how many funnels will fill the can?"},{"who":"Student","text":"It takes exactly three full cone funnels of water to fill the cylinder can! The math matches the physics perfectly!"}],"extras":[{"title":"Tip","text":"Understand the properties of cylinders and cones to calculate areas, volumes, and solve real-life problems effectively."}]},{"n":32,"en":"THE SPHERE","vi":"HÌNH CẦU","page":32,"focus":"","cards":[{"t":"sphere","pos":"noun","ipa":"/sfɪə/","vi":"hình cầu","ex":"A solid sphere is generated when we rotate a semicircle around its bounding diameter."},{"t":"spherical surface","pos":"noun phrase","ipa":"/ˈsfer.ɪ.kəl ˈsɜː.fɪs/","vi":"mặt cầu","ex":"The spherical surface consists of all points in space that are equidistant from a fixed center point."},{"t":"center","pos":"noun","ipa":"/ˈsen.tə/","vi":"tâm (hình cầu / mặt cầu)","ex":"The center of the sphere is represented by the point O inside the diagram."},{"t":"radius","pos":"noun, plural: radii","ipa":"/ˈreɪ.di.əs/","vi":"bán kính","ex":"If the radius of the sphere is R, its surface area can be computed as 4πR²."},{"t":"diameter","pos":"noun","ipa":"/daɪˈæm.ɪ.tə/","vi":"đường kính","ex":"A standard FIFA football has a diameter of approximately twenty-two centimeters."},{"t":"fixed diameter","pos":"noun phrase","ipa":"/fɪkst daɪˈæm.ɪ.tə/","vi":"đường kính cố định","ex":"When a semicircle rotates around its fixed diameter, it sweeps out a solid sphere."},{"t":"hemisphere","pos":"noun","ipa":"/ˈhem.ɪ.sfɪə/","vi":"bán cầu / nửa hình cầu","ex":"A hemisphere is exactly half of a sphere, bounded by a circular flat base."},{"t":"semicircle","pos":"noun","ipa":"/ˈsem.iˌsɜː.kəl/","vi":"nửa hình tròn","ex":"Rotating a semicircle about its bounding diameter generates the corresponding solid sphere."},{"t":"cutting plane","pos":"noun phrase","ipa":"/ˈkʌt.ɪŋ pleɪn/","vi":"mặt phẳng cắt","ex":"When a sphere is sliced by a cutting plane, the resulting cross-section is always a flat circle."},{"t":"intersection","pos":"noun","ipa":"/ˌɪn.təˈsek.ʃən/","vi":"phần chung / giao tuyến / mặt cắt","ex":"The intersection of the cutting plane and the sphere is a circular disk."},{"t":"great circle","pos":"noun phrase","ipa":"/ɡreɪt ˈsɜː.kəl/","vi":"đường tròn lớn","ex":"A cutting plane that passes through the center of a sphere creates a great circle on the surface."},{"t":"surface area","pos":"noun phrase","ipa":"/ˈsɜː.fɪs ˈeə.ri.ə/","vi":"diện tích mặt cầu","ex":"Calculate the surface area of a wooden sphere with a diameter of thirty-five centimeters."},{"t":"volume","pos":"noun","ipa":"/ˈvɒl.juːm/","vi":"thể tích hình cầu","ex":"The formula for the volume of a sphere is V = four thirds πR³."},{"t":"equator","pos":"noun","ipa":"/ɪˈkweɪ.tə/","vi":"đường Xích đạo (đường tròn lớn nhất)","ex":"The Earth's equator acts as a great circle with a circumference of approximately forty thousand kilometers."},{"t":"ball bearing","pos":"noun phrase","ipa":"/ˈbɔːl ˌbeə.rɪŋ/","vi":"vòng bi / ổ bi / viên bi thép","ex":"A mechanical ball bearing utilizes steel spheres to reduce friction between moving parts."}],"dlg":[{"who":"Ms. Alice","text":"Class, our cylindrical container holds exactly three tennis balls of diameter 6.4 cm. How do we find its dimensions?"},{"who":"Student","text":"The radius of the container is R = 3.2 cm, and its height is exactly three times the diameter: h = 3 times 6.4 = 19.2 cm!"},{"who":"Ms. Alice","text":"Excellent! Now let's calculate the total volume of the cylinder and the combined volume of the three spherical balls."},{"who":"Student","text":"The cylinder volume is 618 cm³. The three balls have a volume of about 412 cm³!"},{"who":"Ms. Alice","text":"Perfect calculations! What is the remaining empty volume inside the container not occupied by the balls?"},{"who":"Student","text":"We subtract the balls' volume from the cylinder: the empty volume is approximately 618 − 412 = 206 cm³! Geometry is so useful!"}],"extras":[{"title":"Formulas","text":"Surface area of a sphere: S = 4πR². Volume of a sphere: V = four thirds πR³."},{"title":"Key relationships","text":"A cutting plane through a sphere always gives a circle. A cutting plane through the center gives a great circle."}]}];
window.TOAN9_GROUPS = [["Hệ phương trình bậc nhất hai ẩn",1,3],["Phương trình, bất phương trình bậc nhất",4,6],["Căn thức",7,10],["Hệ thức lượng trong tam giác vuông",11,12],["Đường tròn",13,17],["Hàm số y = ax² và phương trình bậc hai",18,21],["Tần số và tần số tương đối",22,24],["Xác suất",25,26],["Góc nội tiếp, đa giác đều",27,30],["Hình trụ, hình nón, hình cầu",31,32]];
